head.b:skin:
:root {
  --yellow: #FFD93D;
  --blue: #6BCBFF;
  --coral: #FF6B6B;
  --purple: #B28DFF;
  --green: #6EE7B7;
  --dark: #2D3436;
  --gray: #636e72;
  --light: #FFF8E7;
  --white: #FFFFFF;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.08);
  --shadow: 0 4px 20px rgba(0,0,0,0.1);
  --shadow-lg: 0 8px 40px rgba(0,0,0,0.15);
  --radius-sm: 10px;
  --radius: 16px;
  --radius-lg: 24px;
  --radius-xl: 32px;
  --font-display: 'Baloo 2', cursive;
  --font-rounded: 'Fredoka', sans-serif;
  --font-body: 'Nunito', sans-serif;
  --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --bounce: cubic-bezier(0.68, -0.55, 0.265, 1.55);
}
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth;overflow-x:hidden}
body{font-family:var(--font-body);background:var(--white);color:var(--dark);line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}
a{text-decoration:none;color:inherit}
ul{list-style:none}
.container{max-width:1200px;margin:0 auto;padding:0 clamp(15px, 3vw, 25px)}
.section{display:block;opacity:1}
.section-title{font-family:var(--font-display);font-size:clamp(1.4rem, 4.5vw, 2.2rem);text-align:center;margin-bottom:clamp(20px, 4vw, 40px);color:var(--dark);position:relative;padding-bottom:15px}
.section-title::after{content:'';position:absolute;bottom:0;left:50%;transform:translateX(-50%);width:80px;height:4px;border-radius:2px;background:linear-gradient(90deg,var(--coral),var(--yellow))}

/* Wave Elements Positioning */
.wave-top {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 60px;
  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 1200 120' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0,60 C300,120 700,0 1200,60 L1200,0 L0,0 Z' fill='%23FFF8E7'/%3E%3C/svg%3E") no-repeat;
  background-size: 100% 60px;
  z-index: 5;
  pointer-events: none;
}
.wave-bottom {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 60px;
  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 1200 120' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0,0 C300,60 700,120 1200,60 L1200,120 L0,120 Z' fill='%23FFF8E7'/%3E%3C/svg%3E") no-repeat;
  background-size: 100% 60px;
  z-index: 5;
  pointer-events: none;
}
@media (max-width: 768px) {
  .wave-top {
    height: 40px;
    background-size: 100% 40px;
  }
  .wave-bottom {
    height: 40px;
    background-size: 100% 40px;
  }
}

@keyframes float{0%,100%{transform:translateY(0) rotate(0deg)}50%{transform:translateY(-20px) rotate(3deg)}}
@keyframes floatCloud{0%{transform:translateX(-100px) translateY(0)}50%{transform:translateX(20px) translateY(-15px)}100%{transform:translateX(-100px) translateY(0)}}
@keyframes twinkle{0%,100%{opacity:1}50%{opacity:0.3}}
@keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}
@keyframes bounceIn{0%{transform:scale(0);opacity:0}60%{transform:scale(1.1)}100%{transform:scale(1);opacity:1}}
@keyframes wiggle{0%,100%{transform:rotate(0deg)}25%{transform:rotate(-5deg)}75%{transform:rotate(5deg)}}
@keyframes gradientShift{0%{background-position:0% 50%}50%{background-position:100% 50%}100%{background-position:0% 50%}}
@keyframes musicNote{0%{transform:translateY(100px) rotate(0deg);opacity:0}50%{opacity:1}100%{transform:translateY(-200px) rotate(720deg);opacity:0}}
@keyframes glow{0%,100%{box-shadow:0 0 20px rgba(255,107,107,0.4)}50%{box-shadow:0 0 40px rgba(255,107,107,0.7)}}
@keyframes slideUp{0%{transform:translateY(40px);opacity:0}100%{transform:translateY(0);opacity:1}}
@keyframes scaleIn{0%{transform:scale(0.8);opacity:0}100%{transform:scale(1);opacity:1}}
@keyframes shimmer{0%{background-position:-200% 0}100%{background-position:200% 0}}
@keyframes cloudDrift{0%{transform:translateX(-100%)}100%{transform:translateX(100vw)}}
@keyframes scrollHint{0%,100%{transform:translateX(0);opacity:0.5}50%{transform:translateX(10px);opacity:1}}

/* Safe Animation Observer system (prevents blank/hidden elements when JS fails) */
body.js-active .fade-in{opacity:0;transform:translateY(30px);transition:opacity 0.6s ease,transform 0.6s ease}
body.js-active .fade-in.visible{opacity:1;transform:translateY(0)}
body.js-active .fade-in-scale{opacity:0;transform:scale(0.8);transition:opacity 0.5s ease,transform 0.5s var(--bounce)}
body.js-active .fade-in-scale.visible{opacity:1;transform:scale(1)}

.card{background:var(--white);border-radius:var(--radius);box-shadow:var(--shadow);overflow:hidden;transition:var(--transition)}
@media(hover: hover){
  .card:hover{transform:translateY(-5px);box-shadow:var(--shadow-lg)}
}
.gradient-text{background:linear-gradient(135deg,var(--coral),var(--yellow),var(--blue));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
#secSearch{position:fixed;top:0;left:0;width:100%;height:100%;z-index:10000;background:linear-gradient(135deg,rgba(255,107,107,0.97),rgba(107,203,255,0.97),rgba(178,141,255,0.97),rgba(255,217,61,0.97));background-size:400% 400%;animation:gradientShift 15s ease infinite;display:none;justify-content:center;align-items:center;padding:20px}
#secSearch.active{display:flex}
.search-overlay-close{position:absolute;top:20px;right:30px;background:none;border:none;color:#fff;font-size:2rem;cursor:pointer;transition:var(--transition);z-index:10001}
.search-overlay-close:hover{transform:rotate(90deg)}
.search-overlay-inner{width:100%;max-width:600px;text-align:center}
.search-overlay-inner h2{font-family:var(--font-display);color:#fff;font-size:2rem;margin-bottom:30px}
.search-form{display:flex;gap:15px;margin-bottom:30px}
.search-form input{flex:1;padding:18px 25px;border:3px solid transparent;border-radius:50px;font-family:var(--font-body);font-size:1.1rem;outline:none;background:rgba(255,255,255,0.95);transition:var(--transition)}
.search-form input:focus{border-color:var(--yellow);box-shadow:0 0 20px rgba(255,217,61,0.3)}
.search-form button{padding:18px 35px;border:none;border-radius:50px;background:var(--yellow);color:var(--dark);font-family:var(--font-display);font-size:1.1rem;font-weight:700;cursor:pointer;transition:var(--transition);display:flex;align-items:center;gap:10px}
@media(hover: hover){
  .search-form button:hover{transform:scale(1.05);box-shadow:0 0 20px rgba(255,217,61,0.5)}
}
.popular-tags{color:rgba(255,255,255,0.9)}
.popular-tags p{margin-bottom:12px;font-size:0.95rem}
.popular-tags .tag-chips{display:flex;flex-wrap:wrap;gap:10px;justify-content:center}
.popular-tags .tag-chips span{padding:8px 20px;background:rgba(255,255,255,0.2);border-radius:50px;font-size:0.9rem;cursor:pointer;transition:var(--transition);border:1px solid rgba(255,255,255,0.3)}
@media(hover: hover){
  .popular-tags .tag-chips span:hover{background:rgba(255,255,255,0.35);transform:scale(1.05)}
}
#secHeader{position:fixed;top:0;left:0;width:100%;z-index:9999;padding:15px 0;transition:var(--transition);background:rgba(255,255,255,0.85);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px)}
#secHeader.scrolled{box-shadow:0 2px 20px rgba(0,0,0,0.1);padding:8px 0}
.header-inner{display:flex;align-items:center;justify-content:space-between;max-width:1200px;margin:0 auto;padding:0 20px}
.header-logo{display:flex;align-items:center;gap:10px;font-family:var(--font-display);font-size:clamp(1.2rem, 3vw, 1.5rem);font-weight:800;color:var(--coral)}
.header-logo:hover{animation:wiggle 0.5s ease}
.header-logo span{font-size:1.8rem}
.header-nav{display:flex;gap:5px}
.header-nav a{padding:8px 16px;border-radius:50px;font-family:var(--font-rounded);font-size:0.95rem;font-weight:500;color:var(--dark);transition:var(--transition)}
.header-nav a:hover,.header-nav a.active{background:linear-gradient(135deg,var(--coral),var(--purple));color:#fff;box-shadow:0 4px 15px rgba(255,107,107,0.3)}
.header-actions{display:flex;align-items:center;gap:10px}
.header-search-btn,.header-menu-btn{background:none;border:none;font-size:1.2rem;color:var(--dark);padding:10px;cursor:pointer;border-radius:50%;transition:var(--transition)}
.header-search-btn:hover{background:rgba(107,203,255,0.15);color:var(--blue);transform:scale(1.1)}
.header-menu-btn{display:none;font-size:1.5rem}
.header-menu-btn:hover{background:rgba(255,107,107,0.15);color:var(--coral)}
.mobile-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  background: var(--white);
  box-shadow: 0 10px 25px rgba(0,0,0,0.1);
  border-bottom: 3px solid var(--purple);
  overflow: hidden;
  max-height: 0;
  transition: max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 99999;
}
.mobile-dropdown.active {
  max-height: 450px;
}
.mobile-nav {
  display: flex;
  flex-direction: column;
  padding: 15px 20px;
  gap: 5px;
}
.mobile-nav a {
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 12px 18px;
  border-radius: var(--radius-sm);
  font-family: var(--font-rounded);
  font-size: 1rem;
  font-weight: 500;
  color: var(--dark);
  transition: var(--transition);
}
.mobile-nav a i {
  width: 24px;
  text-align: center;
  color: var(--coral);
  font-size: 1.1rem;
}
.mobile-nav a:hover, .mobile-nav a.active {
  background: linear-gradient(135deg, var(--coral), var(--purple));
  color: #fff;
}
.mobile-nav a:hover i, .mobile-nav a.active i {
  color: #fff;
}

/* Spacing and Dimensions optimization for all sections */
#secHero{padding:clamp(100px, 12vw, 140px) 0 clamp(60px, 8vw, 80px);background:linear-gradient(135deg,#FFD93D,#FF6B6B,#B28DFF,#6BCBFF);background-size:400% 400%;animation:gradientShift 15s ease infinite;position:relative;overflow:hidden;min-height:clamp(450px, 90vh, 900px);display:flex;align-items:center}
.cloud{position:absolute;opacity:0.15;font-size:4rem;color:#fff;pointer-events:none}
.cloud1{top:10%;animation:cloudDrift 25s linear infinite}
.cloud2{top:30%;animation:cloudDrift 35s linear infinite;animation-delay:-10s;font-size:5rem;opacity:0.1}
.cloud3{top:55%;animation:cloudDrift 20s linear infinite;animation-delay:-5s;font-size:3.5rem}
.floating-note{position:absolute;font-size:2rem;pointer-events:none;animation:musicNote 6s ease-in infinite}
.floating-note:nth-child(1){left:10%;animation-delay:0s}
.floating-note:nth-child(2){left:30%;animation-delay:2s;font-size:1.5rem}
.floating-note:nth-child(3){left:60%;animation-delay:4s;font-size:2.5rem}
.floating-note:nth-child(4){left:80%;animation-delay:1s;font-size:1.8rem}
.floating-star{position:absolute;font-size:1.5rem;pointer-events:none;animation:twinkle 3s ease-in-out infinite}
.floating-star:nth-child(5){top:15%;left:20%;animation-delay:0.5s}
.floating-star:nth-child(6){top:40%;left:70%;animation-delay:1.5s}
.floating-star:nth-child(7){top:60%;left:15%;animation-delay:2.5s}
.floating-star:nth-child(8){top:75%;left:85%;animation-delay:1s}
.hero-content{position:relative;z-index:2;text-align:center;color:#fff;max-width:800px;margin:0 auto;padding:0 clamp(15px, 3vw, 25px)}
.hero-title{font-family:var(--font-display);font-size:clamp(1.8rem, 6vw, 3.5rem);font-weight:800;margin-bottom:20px;animation:bounceIn 1s var(--bounce);text-shadow:0 4px 15px rgba(0,0,0,0.2);line-height:1.2}
.hero-subtitle{font-family:var(--font-body);font-size:clamp(0.95rem, 2.5vw, 1.25rem);margin-bottom:clamp(20px, 4vw, 40px);opacity:0;animation:slideUp 0.8s ease forwards;animation-delay:0.5s;text-shadow:0 2px 10px rgba(0,0,0,0.15);line-height:1.6}
.hero-cta{display:flex;gap:20px;justify-content:center;flex-wrap:wrap;opacity:0;animation:slideUp 0.8s ease forwards;animation-delay:0.8s}
.btn-primary{padding:16px 40px;border:none;border-radius:50px;font-family:var(--font-display);font-size:1.1rem;font-weight:700;cursor:pointer;transition:var(--transition);display:inline-flex;align-items:center;gap:10px;background:linear-gradient(135deg,var(--coral),#FF8A5C);color:#fff;box-shadow:0 4px 20px rgba(255,107,107,0.4)}
@media(hover: hover){
  .btn-primary:hover{transform:translateY(-3px);box-shadow:0 8px 30px rgba(255,107,107,0.6)}
}
.btn-secondary{padding:16px 40px;border:none;border-radius:50px;font-family:var(--font-display);font-size:1.1rem;font-weight:700;cursor:pointer;transition:var(--transition);display:inline-flex;align-items:center;gap:10px;background:var(--yellow);color:var(--dark);box-shadow:0 4px 20px rgba(255,217,61,0.4);animation:pulse 2s ease infinite}
@media(hover: hover){
  .btn-secondary:hover{transform:translateY(-3px);box-shadow:0 8px 30px rgba(255,217,61,0.7)}
}
.hero-mascot{position:absolute;bottom:20px;right:5%;width:80px;height:80px;background:linear-gradient(135deg,var(--yellow),var(--coral));border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:2.5rem;box-shadow:0 4px 20px rgba(0,0,0,0.2);animation:float 3s ease-in-out infinite;z-index:2}
.hero-mascot::after{content:'🎵';animation:wiggle 2s ease-in-out infinite}

/* Layout Padding System */
#secCategories, #secVideos, #secShorts, #secABC, #secHindi, #secCounting, #secAnimals, #secColors, #secTrust, #secSubscribe, #secBlog {
  padding: clamp(40px, 6vw, 60px) 0;
}
#secCategories { background:var(--light); }
.categories-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(15px, 2.5vw, 25px)}
.category-card{border-radius:var(--radius);padding:clamp(20px, 3.5vw, 35px) clamp(15px, 2.5vw, 25px);text-align:center;cursor:pointer;transition:var(--transition);box-shadow:var(--shadow);position:relative;overflow:hidden}
.category-card::before{content:'';position:absolute;top:0;left:0;width:100%;height:4px}
@media(hover: hover){
  .category-card:hover{transform:translateY(-8px);box-shadow:var(--shadow-lg)}
}
.category-card .cat-emoji{font-size:clamp(2.2rem, 5vw, 3.5rem);margin-bottom:15px;display:block}
.category-card .cat-name{font-family:var(--font-display);font-size:clamp(1.1rem, 2.5vw, 1.4rem);font-weight:700;color:#fff;margin-bottom:8px}
.category-card .cat-link{font-family:var(--font-rounded);font-size:0.9rem;color:rgba(255,255,255,0.85);display:inline-flex;align-items:center;gap:5px;transition:var(--transition)}
@media(hover: hover){
  .category-card:hover .cat-link{gap:10px}
}
.cat-abc{background:linear-gradient(135deg,#FF6B6B,#ee5a24)}
.cat-123{background:linear-gradient(135deg,#6BCBFF,#0984e3)}
.cat-colors{background:linear-gradient(135deg,#B28DFF,#6c5ce7)}
.cat-animals{background:linear-gradient(135deg,#6EE7B7,#00b894)}
.cat-hindi{background:linear-gradient(135deg,#FFD93D,#fdcb6e)}
.cat-songs{background:linear-gradient(135deg,#FF8A5C,#e17055)}

#secVideos{background:var(--white);}
.videos-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(15px, 2.5vw, 25px)}
.video-card{border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow);background:var(--white);transition:var(--transition);cursor:pointer}
@media(hover: hover){
  .video-card:hover{transform:scale(1.03);box-shadow:var(--shadow-lg)}
}
.video-thumb{width:100%;aspect-ratio:16/9;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden}
.video-thumb .play-circle{width:clamp(45px, 7vw, 70px);height:clamp(45px, 7vw, 70px);background:rgba(255,255,255,0.95);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:clamp(1.1rem, 2vw, 1.8rem);color:var(--coral);transition:var(--transition);box-shadow:0 4px 15px rgba(0,0,0,0.2);z-index:2}
@media(hover: hover){
  .video-card:hover .play-circle{animation:pulse 1.5s ease infinite}
}
.video-info{padding:clamp(12px, 2vw, 18px) clamp(10px, 1.8vw, 20px)}
.video-info h3{font-family:var(--font-display);font-size:clamp(0.95rem, 2vw, 1.1rem);font-weight:600;margin-bottom:8px;color:var(--dark)}
.video-info .views{font-family:var(--font-body);font-size:0.85rem;color:var(--gray);display:flex;align-items:center;gap:6px}

#secShorts{background:var(--light);}
.shorts-carousel{display:flex;gap:20px;overflow-x:auto;padding:20px 10px 30px;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;scrollbar-width:thin;scrollbar-color:var(--coral) var(--light)}
.shorts-carousel::-webkit-scrollbar{height:8px}
.shorts-carousel::-webkit-scrollbar-track{background:var(--light);border-radius:4px}
.shorts-carousel::-webkit-scrollbar-thumb{background:linear-gradient(90deg,var(--coral),var(--purple));border-radius:4px}
.short-card{flex:0 0 200px;scroll-snap-align:start;border-radius:var(--radius);aspect-ratio:9/16;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:25px 15px;box-shadow:var(--shadow);transition:var(--transition);cursor:pointer}
@media(hover: hover){
  .short-card:hover{transform:translateY(-5px) scale(1.02);box-shadow:var(--shadow-lg)}
}
.short-card .short-emoji{font-size:3rem;margin-bottom:15px}
.short-card .short-label{font-family:var(--font-display);font-size:0.95rem;font-weight:600;color:#fff;text-align:center}
.scroll-hint{text-align:center;margin-top:10px;color:var(--gray);font-size:0.9rem;animation:scrollHint 2s ease-in-out infinite}
.scroll-hint i{margin-left:5px}

#secABC{background:var(--white);}
.abc-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:clamp(8px, 1.2vw, 12px)}
.abc-letter{aspect-ratio:1;display:flex;align-items:center;justify-content:center;border-radius:var(--radius-sm);font-family:var(--font-display);font-size:clamp(1.2rem, 3.5vw, 1.8rem);font-weight:800;color:#fff;cursor:pointer;transition:var(--transition);box-shadow:var(--shadow-sm)}
@media(hover: hover){
  .abc-letter:hover{transform:scale(1.1) translateY(-3px);box-shadow:var(--shadow)}
}
.abc-l1{background:linear-gradient(135deg,#FF6B6B,#ee5a24)}
.abc-l2{background:linear-gradient(135deg,#6BCBFF,#0984e3)}
.abc-l3{background:linear-gradient(135deg,#B28DFF,#6c5ce7)}
.abc-l4{background:linear-gradient(135deg,#6EE7B7,#00b894)}
.abc-l5{background:linear-gradient(135deg,#FFD93D,#fdcb6e)}
.abc-l6{background:linear-gradient(135deg,#FF8A5C,#e17055)}

#secHindi{background:var(--light);}
.hindi-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:clamp(8px, 1.2vw, 12px)}
.hindi-char{padding:clamp(10px, 2vw, 15px) 5px;text-align:center;border-radius:var(--radius-sm);font-family:var(--font-display);font-size:clamp(1.1rem, 3vw, 1.6rem);font-weight:600;color:var(--purple);background:var(--white);border:2px solid rgba(178,141,255,0.3);cursor:pointer;transition:var(--transition)}
@media(hover: hover){
  .hindi-char:hover{background:var(--purple);color:#fff;transform:scale(1.08);box-shadow:0 4px 15px rgba(178,141,255,0.4);border-color:var(--purple)}
}

#secCounting{background:var(--white);}
.counting-grid{display:grid;grid-template-columns:repeat(10,1fr);gap:clamp(3px, 0.8vw, 8px)}
.count-num{padding:clamp(4px, 1.2vw, 10px) 2px;text-align:center;border-radius:var(--radius-sm);font-family:var(--font-display);font-size:clamp(0.65rem, 2vw, 1rem);font-weight:600;cursor:pointer;transition:var(--transition);background:var(--light)}
.count-num:nth-child(odd){color:var(--coral)}
.count-num:nth-child(even){color:var(--blue)}
@media(hover: hover){
  .count-num:hover{background:var(--yellow);transform:scale(1.15);box-shadow:var(--shadow);color:var(--dark)!important;z-index:2}
}

#secAnimals{background:var(--light);}
.animals-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(12px, 2vw, 20px)}
.animal-card{background:var(--white);border-radius:var(--radius);padding:clamp(15px, 3vw, 30px) clamp(10px, 2vw, 20px);text-align:center;box-shadow:var(--shadow);transition:var(--transition);cursor:pointer}
@media(hover: hover){
  .animal-card:hover{transform:translateY(-8px) rotate(2deg);box-shadow:var(--shadow-lg)}
}
.animal-card .animal-emoji{font-size:clamp(2.5rem, 5vw, 3.5rem);margin-bottom:12px;display:block}
.animal-card .animal-name{font-family:var(--font-display);font-size:clamp(1.1rem, 2vw, 1.3rem);font-weight:700;color:var(--dark);margin-bottom:5px}
.animal-card .animal-sound{font-family:var(--font-rounded);font-size:0.9rem;color:var(--gray);font-style:italic}

#secColors{background:var(--white);}
.colors-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:clamp(8px, 1.5vw, 15px)}
.color-swatch{aspect-ratio:1;border-radius:var(--radius);display:flex;align-items:center;justify-content:center;font-family:var(--font-display);font-size:clamp(0.75rem, 2vw, 1.1rem);font-weight:700;cursor:pointer;transition:var(--transition);text-transform:capitalize;position:relative}
@media(hover: hover){
  .color-swatch:hover{transform:scale(1.1);box-shadow:var(--shadow-lg);z-index:2}
}
.color-white{color:var(--dark)}

#secTrust{background:var(--light);}
.trust-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:25px}
.trust-card{background:var(--white);border-radius:var(--radius);padding:35px 25px;text-align:center;box-shadow:var(--shadow);transition:var(--transition)}
@media(hover: hover){
  .trust-card:hover{transform:translateY(-8px);box-shadow:var(--shadow-lg)}
}
.trust-card i{font-size:2.5rem;color:var(--coral);margin-bottom:18px;display:block}
.trust-card h3{font-family:var(--font-display);font-size:1.3rem;font-weight:700;margin-bottom:10px;color:var(--dark)}
.trust-card p{font-family:var(--font-body);font-size:0.95rem;color:var(--gray);line-height:1.5}

#secSubscribe{background:linear-gradient(135deg,var(--coral),#FF8A5C);position:relative;overflow:hidden;text-align:center}
.subscribe-inner{position:relative;z-index:2;max-width:700px;margin:0 auto;padding:0 20px}
.subscribe-inner h2{font-family:var(--font-display);font-size:2.5rem;color:#fff;margin-bottom:15px}
.subscribe-inner p{font-family:var(--font-body);font-size:1.1rem;color:rgba(255,255,255,0.9);margin-bottom:35px}
.subscribe-btn{display:inline-flex;align-items:center;gap:12px;padding:18px 45px;background:#fff;border:none;border-radius:50px;font-family:var(--font-display);font-size:1.15rem;font-weight:700;color:var(--coral);cursor:pointer;transition:var(--transition);box-shadow:0 4px 20px rgba(0,0,0,0.15)}
@media(hover: hover){
  .subscribe-btn:hover{transform:translateY(-3px);box-shadow:0 8px 30px rgba(0,0,0,0.25)}
}
.subscribe-btn i{color:#FF0000;font-size:1.3rem}
.subscribe-floating{position:absolute;pointer-events:none;font-size:1.8rem;animation:musicNote 7s ease-in infinite}
.subscribe-floating:nth-child(1){left:10%;animation-delay:0s}
.subscribe-floating:nth-child(2){left:50%;animation-delay:2.5s;font-size:2.2rem}
.subscribe-floating:nth-child(3){right:15%;animation-delay:5s}
.subscribe-floating:nth-child(4){left:30%;animation-delay:1s;font-size:1.5rem}
.subscribe-floating:nth-child(5){right:30%;animation-delay:3.5s}

#secBlog{background:var(--white);}
.blog-posts-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:30px}
.blog-post-card{background:var(--white);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow);transition:var(--transition)}
@media(hover: hover){
  .blog-post-card:hover{transform:translateY(-5px);box-shadow:var(--shadow-lg)}
}
.post-featured-img{width:100%;height:220px;object-fit:cover}
.post-gradient-placeholder{width:100%;height:220px;display:flex;align-items:center;justify-content:center;font-size:3rem}
.post-content{padding:22px 25px}
.post-content h2{font-family:var(--font-display);font-size:1.3rem;font-weight:700;margin-bottom:10px;color:var(--dark)}
.post-content h2 a{transition:var(--transition)}
.post-content h2 a:hover{color:var(--coral)}
.post-meta{font-family:var(--font-body);font-size:0.85rem;color:var(--gray);margin-bottom:12px;display:flex;align-items:center;gap:15px;flex-wrap:wrap}
.post-meta i{margin-right:4px}
.post-snippet{font-family:var(--font-body);font-size:0.95rem;color:var(--gray);line-height:1.6;margin-bottom:15px}
.post-labels{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:15px}
.post-labels a{padding:4px 14px;background:var(--light);border-radius:50px;font-size:0.8rem;font-family:var(--font-rounded);color:var(--gray);transition:var(--transition)}
.post-labels a:hover{background:var(--coral);color:#fff}
.blog-pagination{display:flex;justify-content:center;gap:15px;margin-top:40px}
.blog-pagination a{padding:12px 30px;background:var(--light);border-radius:50px;font-family:var(--font-rounded);font-weight:600;transition:var(--transition);color:var(--dark);display:inline-flex;align-items:center;gap:8px}
.blog-pagination a:hover{background:var(--coral);color:#fff;box-shadow:0 4px 15px rgba(255,107,107,0.3)}

#secSingle{background:var(--white);}
.single-post{max-width:800px;margin:0 auto;padding:clamp(100px,8vw,130px) 20px clamp(40px,6vw,60px)}
.single-post .post-featured-img{width:100%;height:auto;max-height:500px;object-fit:cover;border-radius:var(--radius);margin-bottom:30px}
.single-post h1,.single-post .post-title{font-family:var(--font-display);font-size:2.2rem;font-weight:800;margin-bottom:15px;color:var(--dark)}
.single-post .post-meta{margin-bottom:20px;font-size:0.95rem;color:var(--gray);display:flex;gap:20px;flex-wrap:wrap}
.single-post .post-meta span{display:flex;align-items:center;gap:6px}
.single-post .post-body{font-family:var(--font-body);font-size:1.05rem;line-height:1.8;color:var(--dark)}
/* CMS Content Styling System */
.single-post .post-body h2, .single-post .post-body h3, .single-post .post-body h4 { font-family:var(--font-display); margin:30px 0 15px; color:var(--dark); }
.single-post .post-body h2 { font-size: 1.8rem; border-bottom: 2px solid var(--light); padding-bottom: 10px; }
.single-post .post-body h3 { font-size: 1.5rem; color: var(--coral); }
.single-post .post-body h4 { font-size: 1.2rem; }
.single-post .post-body p { margin-bottom:18px; line-height: 1.8; }
.single-post .post-body a { color: var(--blue); text-decoration: none; font-weight: 600; }
.single-post .post-body a:hover { text-decoration: underline; }
.single-post .post-body img { max-width:100%; height:auto; border-radius:var(--radius-sm); margin:20px 0; display: block; box-shadow: var(--shadow-sm); }
/* Lists */
.single-post .post-body ul, .single-post .post-body ol { margin: 0 0 20px 20px; padding-left: 20px; }
.single-post .post-body ul li, .single-post .post-body ol li { margin-bottom: 10px; line-height: 1.6; }
.single-post .post-body ul li { list-style-type: '⭐ '; }
/* Blockquotes */
.single-post .post-body blockquote { margin: 20px 0; padding: 15px 25px; border-left: 5px solid var(--purple); background: var(--light); border-radius: 0 var(--radius-sm) var(--radius-sm) 0; font-style: italic; color: #555; }
/* Code and Pre */
.single-post .post-body code { font-family: monospace; background: #f4f4f4; padding: 2px 6px; border-radius: 4px; font-size: 0.9em; color: var(--coral); }
.single-post .post-body pre { background: #282c34; color: #abb2bf; padding: 15px; border-radius: var(--radius-sm); overflow-x: auto; margin: 20px 0; }
.single-post .post-body pre code { background: transparent; color: inherit; padding: 0; }
/* Tables */
.single-post .post-body table { width: 100%; border-collapse: collapse; margin: 20px 0; overflow-x: auto; display: block; }
.single-post .post-body th, .single-post .post-body td { border: 1px solid #eee; padding: 12px 15px; text-align: left; }
.single-post .post-body th { background: var(--light); font-family: var(--font-rounded); color: var(--dark); }
.single-post .post-body tr:nth-child(even) { background: #fafafa; }
/* Responsive Video Iframes */
.single-post .post-body .video-wrapper { position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; max-width: 100%; border-radius: var(--radius-sm); margin: 20px 0; box-shadow: var(--shadow-sm); }
.single-post .post-body .video-wrapper iframe, .single-post .post-body .video-wrapper object, .single-post .post-body .video-wrapper embed { position: absolute; top: 0; left: 0; width: 100%; height: 100%; border: 0; }
/* Custom Interactive Wrapper */
.single-post .post-body .interactive-widget { background: var(--white); border: 2px solid var(--purple); border-radius: var(--radius); padding: 20px; margin: 30px 0; box-shadow: var(--shadow); position: relative; overflow: visible; }
.post-nav{display:flex;justify-content:space-between;gap:20px;margin-top:50px;padding-top:30px;border-top:1px solid #eee}
.post-nav a{flex:1;padding:20px;background:var(--light);border-radius:var(--radius);transition:var(--transition);font-family:var(--font-rounded);font-size:0.95rem}
.post-nav a:hover{background:var(--coral);color:#fff}
.post-nav .prev{text-align:left}
.post-nav .next{text-align:right}
.post-nav .nav-label{display:block;font-size:0.8rem;color:var(--gray);margin-bottom:5px}
.post-nav a:hover .nav-label{color:rgba(255,255,255,0.7)}
.read-more-link{display:inline-flex;align-items:center;gap:6px;margin-top:12px;font-family:var(--font-rounded);font-size:0.9rem;font-weight:700;color:var(--coral);transition:var(--transition)}
.read-more-link:hover{gap:10px;color:var(--purple)}

#secSearchResults{background:var(--white);}
.search-results-header{text-align:center;margin-bottom:40px}
.search-results-header h2{font-family:var(--font-display);font-size:1.8rem;color:var(--dark);margin-bottom:10px}
.search-results-header .search-query{font-family:var(--font-rounded);color:var(--gray)}
.no-results{text-align:center;padding:60px 20px}
.no-results-icon{font-size:4rem;color:var(--coral);margin-bottom:20px;display:block}
.no-results h3{font-family:var(--font-display);font-size:1.5rem;margin-bottom:15px;color:var(--dark)}
.no-results p{font-family:var(--font-body);color:var(--gray);margin-bottom:25px}
.no-results .btn-primary{display:inline-flex}

#secError{background:var(--light);display:flex;align-items:center;text-align:center}
.error-code{font-family:var(--font-display);font-size:8rem;font-weight:800;background:linear-gradient(135deg,var(--coral),var(--purple),var(--blue));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;animation:bounceIn 1s var(--bounce);margin-bottom:20px;line-height:1}
.error-message{font-family:var(--font-display);font-size:1.8rem;color:var(--dark);margin-bottom:15px}
.error-text{font-family:var(--font-body);font-size:1.1rem;color:var(--gray);margin-bottom:35px}
.error-actions{display:flex;gap:20px;justify-content:center;flex-wrap:wrap}

#secBottomNav{position:fixed;bottom:0;left:0;width:100%;z-index:9990;background:var(--white);box-shadow:0 -2px 20px rgba(0,0,0,0.1);padding:8px 0;padding-bottom:calc(8px + env(safe-area-inset-bottom,0px));display:none}
.bottom-nav-inner{display:flex;justify-content:space-around;align-items:center;max-width:500px;margin:0 auto;padding:0 10px}
.bottom-nav-item{display:flex;flex-direction:column;align-items:center;gap:3px;padding:8px 12px;border-radius:var(--radius-sm);transition:var(--transition);color:var(--gray);font-family:var(--font-rounded);font-size:0.7rem;font-weight:500;cursor:pointer}
.bottom-nav-item i{font-size:1.2rem;transition:var(--transition)}
.bottom-nav-item:hover,.bottom-nav-item.active{color:var(--coral)}
.bottom-nav-item:hover i,.bottom-nav-item.active i{transform:scale(1.1)}

#secScrollTop{position:fixed;bottom:30px;right:30px;z-index:9980;opacity:0;visibility:hidden;transition:var(--transition)}
#secScrollTop.visible{opacity:1;visibility:visible}
.scroll-top-btn{width:55px;height:55px;border:none;border-radius:50%;background:linear-gradient(135deg,var(--purple),var(--blue));color:#fff;font-size:1.3rem;cursor:pointer;box-shadow:0 4px 20px rgba(178,141,255,0.4);transition:var(--transition);display:flex;align-items:center;justify-content:center}
@media(hover: hover){
  .scroll-top-btn:hover{transform:translateY(-5px);box-shadow:0 8px 30px rgba(178,141,255,0.6)}
}

#secFooter{background:linear-gradient(135deg,#2D3436,#1a1a2e);padding:60px 0 30px;color:rgba(255,255,255,0.85)}
.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:40px;margin-bottom:40px}
.footer-brand .footer-logo{font-family:var(--font-display);font-size:1.5rem;font-weight:800;color:#fff;margin-bottom:15px;display:flex;align-items:center;gap:10px}
.footer-brand .footer-logo span{font-size:1.8rem}
.footer-brand p{font-family:var(--font-body);font-size:0.9rem;line-height:1.7;margin-bottom:20px;color:rgba(255,255,255,0.6)}
.footer-social{display:flex;gap:12px}
.footer-social a{width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,0.1);display:flex;align-items:center;justify-content:center;color:#fff;font-size:1.1rem;transition:var(--transition)}
@media(hover: hover){
  .footer-social a:hover{transform:translateY(-3px)}
}
.footer-social a:nth-child(1):hover{background:#1877F2}
.footer-social a:nth-child(2):hover{background:#E4405F}
.footer-social a:nth-child(3):hover{background:#FF0000}
.footer-social a:nth-child(4):hover{background:#000}
.footer-col h4{font-family:var(--font-display);font-size:1.1rem;font-weight:700;color:#fff;margin-bottom:20px;position:relative;padding-bottom:10px}
.footer-col h4::after{content:'';position:absolute;bottom:0;left:0;width:30px;height:3px;background:var(--coral);border-radius:2px}
.footer-col ul li{margin-bottom:10px}
.footer-col ul li a{font-family:var(--font-body);font-size:0.9rem;color:rgba(255,255,255,0.6);transition:var(--transition);display:flex;align-items:center;gap:8px}
@media(hover: hover){
  .footer-col ul li a:hover{color:var(--coral);padding-left:5px}
}
.footer-bottom{text-align:center;padding-top:25px;border-top:1px solid rgba(255,255,255,0.1);font-family:var(--font-body);font-size:0.85rem;color:rgba(255,255,255,0.5)}
.footer-bottom a{color:var(--coral);transition:var(--transition)}
.footer-bottom a:hover{color:var(--yellow)}

/* -------------------------------------------------- */
/* Layout Visibility & Spacing System                 */
/* -------------------------------------------------- */
#secSingle,
#secSearchResults {
  padding: clamp(100px, 8vw, 120px) 0 clamp(40px, 6vw, 60px);
  min-height: 70vh;
}

#secBlog {
  padding: clamp(40px, 6vw, 60px) 0;
  min-height: 50vh;
}

/* On non-homepage listing views (archives, labels, etc.), the blog section is the first element, so add top padding to clear the fixed header */
body:not(.is-homepage) #secBlog {
  padding-top: clamp(100px, 8vw, 120px);
}

/* Homepage sections visibility - hide on all non-homepage pages */
#homepageSections {
  display: none;
}
body.is-homepage #homepageSections {
  display: block;
}
/* On homepage, the blog listing section follows the homepage sections so remove extra top padding */
body.is-homepage #secBlog {
  padding-top: 0;
}


/* -------------------------------------------------- */
/* Responsive Styles & Grid Adjustments               */
/* -------------------------------------------------- */
@media(min-width:1200px){
  .hero-mascot{right:calc(50% - 550px)}
}

@media(max-width:992px){
  .header-nav{display:none}
  .header-menu-btn{display:block}
  .categories-grid{grid-template-columns:repeat(2,1fr)}
  .videos-grid{grid-template-columns:repeat(2,1fr)}
  .animals-grid{grid-template-columns:repeat(3,1fr)}
  .colors-grid{grid-template-columns:repeat(5,1fr)}
  .trust-grid{grid-template-columns:repeat(2,1fr)}
  .footer-grid{grid-template-columns:1fr 1fr;gap:30px}
  .abc-grid{grid-template-columns:repeat(5,1fr)}
  .hindi-grid{grid-template-columns:repeat(5,1fr)}
}

@media(max-width:768px){
  .header-nav{display:none}
  .header-menu-btn{display:block}
  .hero-title{font-size:2.2rem}
  .hero-subtitle{font-size:1rem}
  .section-title{font-size:1.6rem}
  .categories-grid{grid-template-columns:repeat(2,1fr);gap:15px}
  .videos-grid{grid-template-columns:repeat(2,1fr);gap:15px}
  .shorts-carousel{padding:15px 0 20px}
  .short-card{flex:0 0 160px}
  .abc-grid{grid-template-columns:repeat(5,1fr);gap:10px}
  .abc-letter{font-size:1.4rem}
  .hindi-grid{grid-template-columns:repeat(5,1fr);gap:10px}
  .hindi-char{font-size:1.3rem}
  .counting-grid{grid-template-columns:repeat(8,1fr);gap:4px}
  .count-num{font-size:0.75rem;padding:6px 2px}
  .animals-grid{grid-template-columns:repeat(2,1fr);gap:15px}
  .colors-grid{grid-template-columns:repeat(4,1fr);gap:10px}
  .color-swatch{font-size:0.9rem}
  .trust-grid{grid-template-columns:repeat(2,1fr);gap:15px}
  .subscribe-inner h2{font-size:1.8rem}
  .blog-posts-grid{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr 1fr;gap:25px}
  .search-form{flex-direction:column}
  .search-form button{width:100%;justify-content:center}
  .error-code{font-size:5rem}
  .post-nav{flex-direction:column}
  .single-post h1{font-size:1.6rem}
  .hero-mascot{width:60px;height:60px;font-size:2rem;bottom:10px;right:3%}
  #secBottomNav{display:block}
  #secFooter{padding-bottom:90px}
  #secScrollTop{bottom:80px}
  #secHeader{padding:10px 0}
  .hero-cta{gap:15px}
  .btn-primary,.btn-secondary{padding:14px 30px;font-size:1rem}

  #secCategories, #secVideos, #secShorts, #secABC, #secHindi, #secCounting, #secAnimals, #secColors, #secTrust, #secSubscribe, #secBlog {
    padding: 40px 0;
  }
  #secHero {
    padding: 100px 0 50px !important;
    min-height: auto !important;
  }
}

@media(max-width:576px){
  .counting-grid{grid-template-columns:repeat(6,1fr)}
  .hero-mascot{position:relative;bottom:auto;right:auto;margin:20px auto 0;width:70px;height:70px;display:flex}
  #kidsPopUp{padding:20px 25px;border-width:6px;border-radius:var(--radius-lg)}
  #kidsPopUp .pop-letter{font-size:3.5rem}
  #kidsPopUp .pop-word{font-size:1.5rem}
}

@media(max-width:480px){
  .categories-grid{grid-template-columns:repeat(2,1fr)}
  .videos-grid{grid-template-columns:repeat(2,1fr)}

  .abc-grid{grid-template-columns:repeat(4,1fr)}
  .hindi-grid{grid-template-columns:repeat(4,1fr)}
  .animals-grid{grid-template-columns:repeat(2,1fr)}

  .colors-grid{grid-template-columns:repeat(3,1fr)}
  .trust-grid{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr}
  .short-card{flex:0 0 130px}
  .subscribe-inner h2{font-size:1.5rem!important}
  .subscribe-inner p{font-size:0.95rem}
  .subscribe-btn{padding:12px 24px;font-size:0.95rem}
}

@media(max-width:360px){
  .container{padding:0 10px}
  .header-inner{padding:0 10px}
  .header-logo{font-size:1.1rem;gap:5px}
  .header-logo span{font-size:1.4rem}
  .header-actions{gap:4px}
  .header-search-btn,.header-menu-btn,.header-sound-btn{padding:6px;font-size:1.1rem}
  .videos-grid{grid-template-columns:1fr;gap:20px}
  .abc-grid{grid-template-columns:repeat(3,1fr)!important;gap:8px!important}
  .abc-letter{font-size:1.25rem!important}
  .hindi-grid{grid-template-columns:repeat(3,1fr)!important;gap:8px!important}
  .hindi-char{font-size:1.15rem!important}
  .counting-grid{grid-template-columns:repeat(5,1fr);gap:3px}
  .count-num{font-size:0.8rem;padding:8px 2px}
}

@media(max-width:320px){
  .colors-grid{grid-template-columns:repeat(2,1fr)}
  .animals-grid{grid-template-columns:1fr}
  .short-card{flex:0 0 110px}
}

@media(max-width:280px){
  .counting-grid{grid-template-columns:repeat(4,1fr)}
}

@media(min-width:769px){
  #secBottomNav{display:none!important}
}

/* Interactive elements styling */
#kidsConfetti {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 99999;
  pointer-events: none;
}
#kidsPopUp {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0);
  background: var(--white);
  padding: 30px 40px;
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-lg);
  border: 8px solid var(--yellow);
  z-index: 100000;
  text-align: center;
  pointer-events: none;
  transition: transform 0.4s var(--bounce), opacity 0.3s ease;
  opacity: 0;
}
#kidsPopUp.active {
  transform: translate(-50%, -50%) scale(1);
  opacity: 1;
}
#kidsPopUp .pop-letter {
  font-family: var(--font-display);
  font-size: 5rem;
  line-height: 1;
  color: var(--coral);
  margin-bottom: 10px;
}
#kidsPopUp .pop-word {
  font-family: var(--font-rounded);
  font-size: 2rem;
  color: var(--dark);
}
.header-sound-btn {
  background: none;
  border: none;
  font-size: 1.2rem;
  color: var(--dark);
  padding: 10px;
  cursor: pointer;
  border-radius: 50%;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.header-sound-btn:hover {
  background: rgba(178,141,255,0.15);
  color: var(--purple);
  transform: scale(1.1);
}
.header-bedtime-btn {
  background: none;
  border: none;
  font-size: 1.2rem;
  color: var(--dark);
  padding: 10px;
  cursor: pointer;
  border-radius: 50%;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.header-bedtime-btn:hover {
  background: rgba(255,217,61,0.15);
  color: var(--yellow);
  transform: scale(1.1);
}
body.bedtime-mode .header-bedtime-btn i {
  color: var(--yellow);
}

/* Bedtime Mode Variable Overrides */
body.bedtime-mode {
  --yellow: #F59E0B;
  --blue: #3B82F6;
  --coral: #EC4899;
  --purple: #8B5CF6;
  --green: #10B981;
  --dark: #E2E8F0;
  --gray: #94A3B8;
  --light: #1E293B;
  --white: #0F172A;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.5);
  --shadow: 0 4px 20px rgba(0,0,0,0.6);
  --shadow-lg: 0 8px 40px rgba(0,0,0,0.8);
  background-color: var(--white);
  color: var(--dark);
}
body, #secHeader, .card, .video-card, .category-card, .animal-card, .trust-card, .blog-post-card {
  transition: background-color 0.5s ease, color 0.5s ease, border-color 0.5s ease, box-shadow 0.3s ease, transform 0.3s ease;
}
body.bedtime-mode #secHeader {
  background: rgba(15,23,42,0.85);
}
body.bedtime-mode .wave-top {
  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 1200 120' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0,60 C300,120 700,0 1200,60 L1200,0 L0,0 Z' fill='%231E293B'/%3E%3C/svg%3E") no-repeat;
  background-size: 100% 60px;
}
body.bedtime-mode .wave-bottom {
  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 1200 120' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0,0 C300,60 700,120 1200,60 L1200,120 L0,120 Z' fill='%231E293B'/%3E%3C/svg%3E") no-repeat;
  background-size: 100% 60px;
}
@media (max-width: 768px) {
  body.bedtime-mode .wave-top { background-size: 100% 40px; }
  body.bedtime-mode .wave-bottom { background-size: 100% 40px; }
}

/* Kids Quiz Section */
#secQuiz {
  background: var(--light);
  padding: clamp(40px, 6vw, 60px) 0;
}
.quiz-container {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: clamp(20px, 4vw, 40px);
  box-shadow: var(--shadow);
  text-align: center;
  border: 4px solid var(--purple);
}
.quiz-header {
  margin-bottom: 25px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 15px;
}
.quiz-score {
  font-family: var(--font-display);
  font-size: 1.8rem;
  color: var(--yellow);
  text-shadow: 0 2px 5px rgba(0,0,0,0.1);
  background: var(--dark);
  padding: 8px 25px;
  border-radius: 50px;
}
body.bedtime-mode .quiz-score {
  color: #fff;
  background: #1E293B;
}
.quiz-instructions {
  font-family: var(--font-rounded);
  font-size: clamp(1.2rem, 3vw, 1.6rem);
  color: var(--dark);
  font-weight: 600;
  min-height: 50px;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1.4;
}
.quiz-start-btn {
  padding: 12px 35px;
  background: linear-gradient(135deg, var(--coral), var(--purple));
  color: #fff;
  border: none;
  border-radius: 50px;
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 4px 15px rgba(178,141,255,0.4);
  transition: var(--transition);
}
.quiz-start-btn:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 25px rgba(178,141,255,0.6);
}
.quiz-options-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(10px, 2vw, 20px);
  margin-top: 20px;
  min-height: 150px;
}
.quiz-option-card {
  background: var(--light);
  border: 3px solid transparent;
  border-radius: var(--radius);
  aspect-ratio: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
  position: relative;
}
.quiz-option-card:hover {
  transform: scale(1.05);
  box-shadow: var(--shadow);
}
.quiz-option-emoji {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  margin-bottom: 5px;
}
.quiz-option-label {
  font-family: var(--font-display);
  font-size: clamp(1.1rem, 2.5vw, 1.4rem);
  font-weight: 700;
  color: var(--dark);
  text-transform: capitalize;
}
@media(max-width: 768px) {
  .quiz-options-grid { grid-template-columns: repeat(2, 1fr); }
}

/* -------------------------------------------------- */
/* Gamification UI & Premium Features Styles          */
/* -------------------------------------------------- */

/* Header stats counters */
.header-stats {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-right: clamp(5px, 2vw, 15px);
}
.stat-chip {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 12px;
  border-radius: 50px;
  font-family: var(--font-rounded);
  font-weight: 700;
  font-size: 0.85rem;
  background: var(--light);
  box-shadow: var(--shadow-sm);
  color: var(--dark);
}
.stat-chip.streak {
  background: linear-gradient(135deg, #FF9F43, #FF5252);
  color: #fff;
}
.stat-chip.stars {
  background: linear-gradient(135deg, #FFD93D, #FFA502);
  color: var(--dark);
}
@media(max-width: 480px) {
  .stat-chip {
    padding: 4px 8px;
    font-size: 0.75rem;
  }
}
@media(max-width: 320px) {
  .header-stats {
    display: none;
  }
}

/* Category Card Locked Overlays */
.category-card.locked {
  position: relative;
  cursor: not-allowed;
  filter: grayscale(0.6);
  opacity: 0.75;
}
.category-card.locked::after {
  content: '🔒 Lock';
  position: absolute;
  top: 10px;
  right: 10px;
  background: rgba(0,0,0,0.6);
  color: #fff;
  font-family: var(--font-rounded);
  font-size: 0.75rem;
  padding: 3px 8px;
  border-radius: 50px;
}
.category-card.locked:hover {
  transform: none !important;
  box-shadow: var(--shadow) !important;
}

/* Gamification panel (daily challenges + badges) */
.gamification-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 25px;
  background: var(--white);
  padding: 18px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  border: 2px solid rgba(107,203,255,0.15);
}
@media(max-width: 768px) {
  .gamification-panel {
    grid-template-columns: 1fr;
    gap: 15px;
  }
}
.gamification-title {
  font-family: var(--font-display);
  font-size: 1.1rem;
  color: var(--dark);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.daily-challenges {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.challenge-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--light);
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-family: var(--font-rounded);
  font-size: 0.9rem;
  color: var(--dark);
  border: 1px solid rgba(0,0,0,0.03);
  transition: var(--transition);
}
.challenge-item.completed {
  background: rgba(110,231,183,0.15);
  border-color: rgba(110,231,183,0.4);
  text-decoration: line-through;
  color: var(--gray);
}
.challenge-progress {
  font-weight: 700;
  color: var(--purple);
}
.challenge-item.completed .challenge-progress {
  color: var(--green);
}
.badge-shelf {
  display: flex;
  justify-content: space-around;
  align-items: center;
  gap: 10px;
  background: var(--light);
  padding: 15px;
  border-radius: var(--radius);
  height: calc(100% - 30px);
  min-height: 80px;
}
.badge-icon {
  font-size: 2.2rem;
  cursor: pointer;
  position: relative;
  transition: transform 0.2s ease, filter 0.2s ease;
  user-select: none;
}
.badge-icon:hover {
  transform: scale(1.2) rotate(5deg);
}
.badge-icon.locked {
  filter: grayscale(1) opacity(0.3);
}
.badge-icon.locked::after {
  content: '🔒';
  position: absolute;
  bottom: -4px;
  right: -4px;
  font-size: 0.9rem;
  filter: none;
}
.badge-tooltip {
  visibility: hidden;
  position: absolute;
  bottom: 120%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--dark);
  color: #fff;
  text-align: center;
  padding: 5px 8px;
  border-radius: 6px;
  font-size: 0.75rem;
  font-family: var(--font-rounded);
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.2s;
  z-index: 10;
  box-shadow: var(--shadow-sm);
}
.badge-icon:hover .badge-tooltip {
  visibility: visible;
  opacity: 1;
}

/* Mascot guide bubble */
.mascot-bubble-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 15px;
  max-width: 600px;
  margin: 0 auto 20px;
  padding: 10px 20px;
  background: rgba(178,141,255,0.08);
  border-radius: var(--radius-lg);
  border: 2px dashed rgba(178,141,255,0.3);
}
.mascot-guide-avatar {
  font-size: 3rem;
  animation: float 2.5s ease-in-out infinite;
  cursor: pointer;
}
.mascot-speech-bubble {
  position: relative;
  background: var(--light);
  border-radius: var(--radius);
  padding: 12px 18px;
  font-family: var(--font-rounded);
  font-size: clamp(0.95rem, 2vw, 1.15rem);
  font-weight: 500;
  color: var(--dark);
  line-height: 1.4;
  flex: 1;
}
.mascot-speech-bubble::before {
  content: '';
  position: absolute;
  top: 50%;
  left: -8px;
  transform: translateY(-50%) rotate(45deg);
  width: 14px;
  height: 14px;
  background: var(--light);
}

/* Game Center Panel tabs */
#secGameCenter {
  background: var(--light);
  padding: clamp(40px, 6vw, 60px) 0;
}
.game-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 25px;
  flex-wrap: wrap;
}
.game-tab-btn {
  padding: 10px 20px;
  border: none;
  border-radius: 50px;
  background: var(--light);
  color: var(--dark);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.95rem;
  cursor: pointer;
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}
.game-tab-btn.active {
  background: linear-gradient(135deg, var(--coral), var(--purple));
  color: #fff;
  box-shadow: 0 4px 15px rgba(255,107,107,0.3);
}
.game-panel {
  display: none;
  animation: scaleIn 0.3s ease;
}
.game-panel.active {
  display: block;
}

/* Tracing Canvas styles */
.tracing-board {
  position: relative;
  width: 320px;
  height: 320px;
  background: var(--white);
  border: 4px dashed var(--coral);
  border-radius: var(--radius-lg);
  margin: 0 auto;
  overflow: hidden;
  cursor: crosshair;
  box-shadow: var(--shadow-sm);
}
canvas#tracingCanvas {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 2;
}
.tracing-guide-letter {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--font-display);
  font-size: 13rem;
  font-weight: 800;
  color: rgba(255,107,107,0.12);
  z-index: 1;
  user-select: none;
  pointer-events: none;
}
.tracing-controls {
  display: flex;
  justify-content: center;
  gap: 15px;
  margin-top: 20px;
}

/* Memory Cards matching styles */
.memory-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  max-width: 420px;
  margin: 15px auto 0;
}
.memory-card {
  aspect-ratio: 1;
  border-radius: var(--radius);
  background: var(--purple);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transform-style: preserve-3d;
  transition: transform 0.5s var(--bounce), background-color 0.3s ease;
  box-shadow: var(--shadow-sm);
  position: relative;
}
.memory-card.flipped {
  transform: rotateY(180deg);
  background: var(--white);
  border: 3px solid var(--purple);
}
.memory-card.matched {
  background: var(--green);
  border-color: var(--green);
  cursor: default;
}
.memory-card .card-back {
  font-size: 2.2rem;
  color: #fff;
  position: absolute;
  backface-visibility: hidden;
}
.memory-card .card-front {
  font-size: 2.5rem;
  transform: rotateY(180deg);
  position: absolute;
  backface-visibility: hidden;
}
@media(max-width: 480px) {
  .memory-grid { gap: 8px; }
  .memory-card .card-back { font-size: 1.8rem; }
  .memory-card .card-front { font-size: 2rem; }
}

/* Drag and Drop Matching styles */
.drag-container {
  display: flex;
  flex-direction: column;
  gap: 25px;
  margin-top: 15px;
}
.drag-source-row {
  display: flex;
  justify-content: center;
  gap: 15px;
}
.drag-card {
  padding: 12px 22px;
  background: var(--white);
  border: 3px dashed var(--blue);
  border-radius: var(--radius);
  cursor: grab;
  font-size: 2.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  user-select: none;
  transition: var(--transition);
}
.drag-card:active {
  cursor: grabbing;
}
.drag-target-row {
  display: flex;
  justify-content: center;
  gap: 15px;
}
.drag-zone {
  padding: 18px 25px;
  background: var(--light);
  border: 3px solid var(--gray);
  border-radius: var(--radius);
  font-family: var(--font-rounded);
  font-weight: 700;
  font-size: 1rem;
  min-width: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}
.drag-zone.drag-hover {
  background: rgba(107,203,255,0.18);
  border-color: var(--blue);
}
.drag-zone.matched {
  background: var(--green);
  border-color: var(--green);
  color: #fff;
  font-size: 0.95rem;
}
@media(max-width: 576px) {
  .drag-source-row, .drag-target-row { flex-direction: column; align-items: center; gap: 8px; }
}

/* Parent dashboard modals */
.parent-modal {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 100002;
  background: rgba(0,0,0,0.6);
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
.parent-modal-inner {
  width: 100%;
  max-width: 420px;
  background: var(--white);
  padding: 30px;
  border-radius: var(--radius-lg);
  text-align: center;
  border: 6px solid var(--blue);
  position: relative;
  box-shadow: var(--shadow-lg);
}

/* -------------------------------------------------- */
/* YouTube Shorts Modal Styles                        */
/* -------------------------------------------------- */
#secShortsModal {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 100000;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  display: none;
  justify-content: center;
  align-items: center;
  padding: 20px;
}
#secShortsModal.active {
  display: flex;
}
.shorts-modal-inner {
  position: relative;
  width: 100%;
  max-width: 400px;
  aspect-ratio: 9 / 16;
  background: var(--dark);
  border-radius: var(--radius-lg);
  border: 4px solid var(--purple);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  transform: scale(0.9);
  transition: transform 0.3s var(--bounce);
}
#secShortsModal.active .shorts-modal-inner {
  transform: scale(1);
}
.shorts-modal-inner iframe {
  width: 100%;
  height: 100%;
  border: none;
  display: block;
}
.shorts-modal-close {
  position: absolute;
  top: 15px;
  right: 15px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.6);
  border: 2px solid #fff;
  color: #fff;
  font-size: 1.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
  z-index: 10;
}
.shorts-modal-close:hover {
  transform: scale(1.1) rotate(90deg);
  background: var(--coral);
}

head.script:
//
document.addEventListener('DOMContentLoaded',function(){
var header=document.getElementById('secHeader');
if(header){window.addEventListener('scroll',function(){if(window.scrollY>50){header.classList.add('scrolled')}else{header.classList.remove('scrolled')}},{passive:true})}

var searchOpen=document.querySelector('.header-search-btn');
var searchOverlay=document.getElementById('secSearch');
var searchClose=document.querySelector('.search-overlay-close');
if(searchOpen&&searchOverlay&&searchClose){
  searchOpen.addEventListener('click',function(){searchOverlay.classList.add('active');document.body.style.overflow='hidden';var inp=searchOverlay.querySelector('input');if(inp)setTimeout(function(){inp.focus()},100)});
  searchClose.addEventListener('click',function(){searchOverlay.classList.remove('active');document.body.style.overflow=''});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&searchOverlay.classList.contains('active')){searchOverlay.classList.remove('active');document.body.style.overflow=''}});
}

var menuOpen = document.querySelector('.header-menu-btn');
var dropdownPanel = document.getElementById('mobileDropdown');

function toggleMenu() {
  if (!dropdownPanel) return;
  var isActive = dropdownPanel.classList.toggle('active');
  var icon = menuOpen.querySelector('i');
  if (icon) {
    if (isActive) {
      icon.className = 'fas fa-times';
      menuOpen.setAttribute('aria-label', 'Close menu');
    } else {
      icon.className = 'fas fa-bars';
      menuOpen.setAttribute('aria-label', 'Open menu');
    }
  }
}

function closeMenu() {
  if (dropdownPanel && dropdownPanel.classList.contains('active')) {
    dropdownPanel.classList.remove('active');
    var icon = menuOpen.querySelector('i');
    if (icon) {
      icon.className = 'fas fa-bars';
      menuOpen.setAttribute('aria-label', 'Open menu');
    }
  }
}

if (menuOpen && dropdownPanel) {
  menuOpen.addEventListener('click', function(e) {
    e.stopPropagation();
    toggleMenu();
  });

  document.addEventListener('click', function(e) {
    var header = document.getElementById('secHeader');
    if (header && !header.contains(e.target)) {
      closeMenu();
    }
  });

  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      closeMenu();
    }
  });
}

// Close mobile dropdown when a link is clicked
document.querySelectorAll('.mobile-nav a').forEach(function(link) {
  link.addEventListener('click', closeMenu);
});

var scrollBtn=document.getElementById('secScrollTop');
if(scrollBtn){
  window.addEventListener('scroll',function(){if(window.scrollY>300){scrollBtn.classList.add('visible')}else{scrollBtn.classList.remove('visible')}},{passive:true});
  scrollBtn.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})});
}

// Intersection Observer animation launcher
var animateElements=document.querySelectorAll('.fade-in,.fade-in-scale,.category-card,.video-card,.short-card,.abc-letter,.hindi-char,.count-num,.animal-card,.color-swatch,.trust-card,.blog-post-card');
if('IntersectionObserver' in window){
  var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}})},{threshold:0.1});
  animateElements.forEach(function(el){observer.observe(el)});
} else {
  animateElements.forEach(function(el){el.classList.add('visible')});
}

var currentPath=window.location.pathname;
document.querySelectorAll('.header-nav a,.mobile-nav a,.bottom-nav-item').forEach(function(link){
  var href=link.getAttribute('href');
  if(href&&currentPath.indexOf(href)!==-1){link.classList.add('active')}
});

document.querySelectorAll('a[href^="#"]').forEach(function(anchor){anchor.addEventListener('click',function(e){var target=document.querySelector(this.getAttribute('href'));if(target){e.preventDefault();target.scrollIntoView({behavior:'smooth',block:'start'})}})});

document.querySelectorAll('.popular-tags .tag-chips span').forEach(function(tag){tag.addEventListener('click',function(){var searchInput=document.querySelector('.search-form input');if(searchInput){searchInput.value=this.textContent;searchInput.focus()}})});

document.querySelectorAll('.category-card').forEach(function(card){card.addEventListener('click',function(){var name=this.querySelector('.cat-name');if(name){var text=name.textContent.toLowerCase();if(text.indexOf('abc')!==-1){document.getElementById('secABC')&&document.getElementById('secABC').scrollIntoView({behavior:'smooth'})}else if(text.indexOf('123')!==-1||text.indexOf('count')!==-1){document.getElementById('secCounting')&&document.getElementById('secCounting').scrollIntoView({behavior:'smooth'})}else if(text.indexOf('hindi')!==-1){document.getElementById('secHindi')&&document.getElementById('secHindi').scrollIntoView({behavior:'smooth'})}else if(text.indexOf('color')!==-1){document.getElementById('secColors')&&document.getElementById('secColors').scrollIntoView({behavior:'smooth'})}else if(text.indexOf('animal')!==-1){document.getElementById('secAnimals')&&document.getElementById('secAnimals').scrollIntoView({behavior:'smooth'})}else if(text.indexOf('song')!==-1){document.getElementById('secVideos')&&document.getElementById('secVideos').scrollIntoView({behavior:'smooth'})}}});
});

var watchBtn=document.querySelector('.btn-primary');
if(watchBtn){watchBtn.addEventListener('click',function(){var videos=document.getElementById('secVideos');if(videos){videos.scrollIntoView({behavior:'smooth'})}})}

// --------------------------------------------------
// Kids Interactive & Fun Soundboard Engine
// --------------------------------------------------
var soundMuted = false;
var audioCtx = null;

function playSynthChime(frequency, type) {
  if (soundMuted) return;
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    var osc = audioCtx.createOscillator();
    var gain = audioCtx.createGain();
    osc.type = type || 'sine';
    osc.frequency.setValueAtTime(frequency || 440, audioCtx.currentTime);
    gain.gain.setValueAtTime(0.15, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.8);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + 0.8);
  } catch (e) {}
}

function playAnimalSound(type) {
  if (soundMuted) return;
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    var osc = audioCtx.createOscillator();
    var gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.type = 'triangle';
    gain.gain.setValueAtTime(0.12, audioCtx.currentTime);

    if (type === 'dog') {
      osc.frequency.setValueAtTime(280, audioCtx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(80, audioCtx.currentTime + 0.12);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.12);
      osc.start();
      osc.stop(audioCtx.currentTime + 0.12);
    } else if (type === 'cat') {
      osc.frequency.setValueAtTime(380, audioCtx.currentTime);
      osc.frequency.linearRampToValueAtTime(580, audioCtx.currentTime + 0.18);
      osc.frequency.linearRampToValueAtTime(480, audioCtx.currentTime + 0.32);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.38);
      osc.start();
      osc.stop(audioCtx.currentTime + 0.38);
    } else if (type === 'frog') {
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(75, audioCtx.currentTime);
      gain.gain.setValueAtTime(0.08, audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.22);
      osc.start();
      osc.stop(audioCtx.currentTime + 0.22);
    } else if (type === 'bird') {
      osc.frequency.setValueAtTime(1150, audioCtx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(1950, audioCtx.currentTime + 0.08);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.1);
      osc.start();
      osc.stop(audioCtx.currentTime + 0.10);
    } else {
      osc.frequency.setValueAtTime(380, audioCtx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(760, audioCtx.currentTime + 0.28);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.28);
      osc.start();
      osc.stop(audioCtx.currentTime + 0.28);
    }
  } catch(e) {}
}

function speakText(text) {
  if (soundMuted) return;
  try {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      var utterance = new SpeechSynthesisUtterance(text);
      utterance.rate = 0.95;
      utterance.pitch = 1.35;
      window.speechSynthesis.speak(utterance);
    }
  } catch (e) {}
}

// Global Confetti Canvas Loop
var canvas = document.getElementById('kidsConfetti');
var particles = [];
var triggerConfetti = function(x, y, customColor) {};

if (canvas) {
  var ctx = canvas.getContext('2d');
  var resizeCanvas = function() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  };
  window.addEventListener('resize', resizeCanvas);
  resizeCanvas();

  function Particle(x, y, color) {
    this.x = x;
    this.y = y;
    this.size = Math.random() * 8 + 4;
    this.speedX = Math.random() * 8 - 4;
    this.speedY = Math.random() * -8 - 4;
    this.gravity = 0.25;
    this.color = color || 'hsl(' + Math.random() * 360 + ', 100%, 65%)';
    this.alpha = 1;
    this.decay = Math.random() * 0.02 + 0.015;
  }

  Particle.prototype.update = function() {
    this.x += this.speedX;
    this.speedY += this.gravity;
    this.y += this.speedY;
    this.alpha -= this.decay;
  };

  Particle.prototype.draw = function() {
    ctx.save();
    ctx.globalAlpha = this.alpha;
    ctx.fillStyle = this.color;
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  };

  triggerConfetti = function(x, y, customColor) {
    var colors = ['#FF6B6B', '#6BCBFF', '#B28DFF', '#6EE7B7', '#FFD93D', '#FF8A5C'];
    for (var i = 0; i < 20; i++) {
      var color = customColor || colors[Math.floor(Math.random() * colors.length)];
      particles.push(new Particle(x, y, color));
    }
  };

  function animateParticles() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (var i = particles.length - 1; i >= 0; i--) {
      var p = particles[i];
      p.update();
      if (p.alpha <= 0) {
        particles.splice(i, 1);
      } else {
        p.draw();
      }
    }
    requestAnimationFrame(animateParticles);
  }
  requestAnimationFrame(animateParticles);
}

