var lullabyPlaying = false;
var lullabyTimer = null;
var bedtimeBtn = document.querySelector('.header-bedtime-btn');

var twinkleMelody = [
  { note: 'C4', freq: 261.63, dur: 500 }, { note: 'C4', freq: 261.63, dur: 500 },
  { note: 'G4', freq: 392.00, dur: 500 }, { note: 'G4', freq: 392.00, dur: 500 },
  { note: 'A4', freq: 440.00, dur: 500 }, { note: 'A4', freq: 440.00, dur: 500 },
  { note: 'G4', freq: 392.00, dur: 1000 },

  { note: 'F4', freq: 349.23, dur: 500 }, { note: 'F4', freq: 349.23, dur: 500 },
  { note: 'E4', freq: 329.63, dur: 500 }, { note: 'E4', freq: 329.63, dur: 500 },
  { note: 'D4', freq: 293.66, dur: 500 }, { note: 'D4', freq: 293.66, dur: 500 },
  { note: 'C4', freq: 261.63, dur: 1000 },

  { note: 'G4', freq: 392.00, dur: 500 }, { note: 'G4', freq: 392.00, dur: 500 },
  { note: 'F4', freq: 349.23, dur: 500 }, { note: 'F4', freq: 349.23, dur: 500 },
  { note: 'E4', freq: 329.63, dur: 500 }, { note: 'E4', freq: 329.63, dur: 500 },
  { note: 'D4', freq: 293.66, dur: 1000 },

  { note: 'G4', freq: 392.00, dur: 500 }, { note: 'G4', freq: 392.00, dur: 500 },
  { note: 'F4', freq: 349.23, dur: 500 }, { note: 'F4', freq: 349.23, dur: 500 },
  { note: 'E4', freq: 329.63, dur: 500 }, { note: 'E4', freq: 329.63, dur: 500 },
  { note: 'D4', freq: 293.66, dur: 1000 },

  { note: 'C4', freq: 261.63, dur: 500 }, { note: 'C4', freq: 261.63, dur: 500 },
  { note: 'G4', freq: 392.00, dur: 500 }, { note: 'G4', freq: 392.00, dur: 500 },
  { note: 'A4', freq: 440.00, dur: 500 }, { note: 'A4', freq: 440.00, dur: 500 },
  { note: 'G4', freq: 392.00, dur: 1000 },

  { note: 'F4', freq: 349.23, dur: 500 }, { note: 'F4', freq: 349.23, dur: 500 },
  { note: 'E4', freq: 329.63, dur: 500 }, { note: 'E4', freq: 329.63, dur: 500 },
  { note: 'D4', freq: 293.66, dur: 500 }, { note: 'D4', freq: 293.66, dur: 500 },
  { note: 'C4', freq: 261.63, dur: 1000 }
];

var currentLullabyNoteIndex = 0;

function playLullabyStep() {
  if (!lullabyPlaying || soundMuted) return;
  var note = twinkleMelody[currentLullabyNoteIndex];

  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    var osc = audioCtx.createOscillator();
    var gain = audioCtx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(note.freq, audioCtx.currentTime);

    gain.gain.setValueAtTime(0.04, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + (note.dur / 1000) - 0.05);

    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + (note.dur / 1000));
  } catch (e) {}

  currentLullabyNoteIndex = (currentLullabyNoteIndex + 1) % twinkleMelody.length;
  lullabyTimer = setTimeout(playLullabyStep, note.dur);
}

if (bedtimeBtn) {
  bedtimeBtn.addEventListener('click', function() {
    var body = document.body;
    var isBedtime = body.classList.toggle('bedtime-mode');
    var icon = this.querySelector('i');

    if (isBedtime) {
      icon.className = 'fas fa-sun';
      this.setAttribute('aria-label', 'Playtime Mode');
      lullabyPlaying = true;
      currentLullabyNoteIndex = 0;
      playLullabyStep();
      speakText("Time for bed. Let's listen to a lullaby.");
    } else {
      icon.className = 'fas fa-moon';
      this.setAttribute('aria-label', 'Bedtime Mode');
      lullabyPlaying = false;
      if (lullabyTimer) clearTimeout(lullabyTimer);
      speakText("Rise and shine! Let's play!");
    }
  });
}

