var quizItems = [
  { term: 'Apple', emoji: '🍎', category: 'fruits', spoken: 'Apple' },
  { term: 'Banana', emoji: '🍌', category: 'fruits', spoken: 'Banana' },
  { term: 'Car', emoji: '🚗', category: 'vehicles', spoken: 'Car' },
  { term: 'Dog', emoji: '🐶', category: 'animals', spoken: 'Dog' },
  { term: 'Cat', emoji: '🐱', category: 'animals', spoken: 'Cat' },
  { term: 'Elephant', emoji: '🐘', category: 'animals', spoken: 'Elephant' },
  { term: 'Lion', emoji: '🦁', category: 'animals', spoken: 'Lion' },
  { term: 'Monkey', emoji: '🐒', category: 'animals', spoken: 'Monkey' },
  { term: 'Fish', emoji: '🐟', category: 'animals', spoken: 'Fish' },
  { term: 'Cow', emoji: '🐄', category: 'animals', spoken: 'Cow' },
  { term: 'Butterfly', emoji: '🦋', category: 'animals', spoken: 'Butterfly' },
  { term: 'Bird', emoji: '🐦', category: 'animals', spoken: 'Bird' },
  { term: 'Train', emoji: '🚂', category: 'vehicles', spoken: 'Train' },
  { term: 'Sun', emoji: '☀️', category: 'nature', spoken: 'Sun' },
  { term: 'Rainbow', emoji: '🌈', category: 'nature', spoken: 'Rainbow' },
  { term: 'Balloon', emoji: '🎈', category: 'toys', spoken: 'Balloon' }
];

var quizScore = 0;
var quizCorrectItem = null;
var quizActive = false;

function generateQuizQuestion() {
  if (!quizActive) return;

  var grid = document.getElementById('quizOptionsGrid');
  var instruction = document.getElementById('quizInstructionText');
  if (!grid || !instruction) return;

  grid.replaceChildren();

  var itemsCopy = quizItems.slice();
  var selectedOptions = [];
  while (selectedOptions.length < 4 && itemsCopy.length > 0) {
    var randIndex = Math.floor(Math.random() * itemsCopy.length);
    selectedOptions.push(itemsCopy.splice(randIndex, 1)[0]);
  }

  quizCorrectItem = selectedOptions[Math.floor(Math.random() * selectedOptions.length)];

  instruction.replaceChildren();
  instruction.appendChild(document.createTextNode('Can you find the '));
  var span = document.createElement('span');
  span.style.color = 'var(--purple)';
  span.style.fontFamily = 'var(--font-display)';
  span.style.fontSize = '1.8rem';
  span.style.marginLeft = '5px';
  span.textContent = quizCorrectItem.emoji + ' ' + quizCorrectItem.term;
  instruction.appendChild(span);
  instruction.appendChild(document.createTextNode('?'));

  setTimeout(function() {
    speakText("Can you find the " + quizCorrectItem.spoken + "?");
  }, 100);

  selectedOptions.forEach(function(item) {
    var card = document.createElement('div');
    card.className = 'quiz-option-card';
    card.replaceChildren();
    var s1 = document.createElement('span');
    s1.className = 'quiz-option-emoji';
    s1.textContent = item.emoji;
    var s2 = document.createElement('span');
    s2.className = 'quiz-option-label';
    s2.textContent = item.term;
    card.appendChild(s1);
    card.appendChild(s2);

    card.addEventListener('click', function() {
      var rect = this.getBoundingClientRect();
      if (item.term === quizCorrectItem.term) {
        triggerConfetti(rect.left + rect.width / 2, rect.top + rect.height / 2, '#6EE7B7');
        playSynthChime(523.25, 'sine');
        setTimeout(function() { playSynthChime(659.25, 'sine'); }, 120);
        setTimeout(function() { playSynthChime(783.99, 'sine'); }, 240);
        setTimeout(function() { playSynthChime(1046.50, 'sine'); }, 360);

        quizScore++;
        document.getElementById('quizScoreValue').textContent = quizScore + " / 5";

        if (quizScore >= 5) {
          instruction.replaceChildren();
          var span = document.createElement('span');
          span.style.color = 'var(--green)';
          span.textContent = '🎉 Quiz Completed! You earned 10 Stars!';
          instruction.appendChild(span);
          speakText("Congratulations! You completed the quiz round!");
          triggerConfetti(window.innerWidth / 2, window.innerHeight / 2, '#FFD93D');
          playLevelUpFanfare();

          GamificationDB.data.completedQuizzes++;
          GamificationDB.addStars(10, "Completed Quiz Round!");

          quizActive = false;
          var startBtn = document.getElementById('quizStartBtn');
          if (startBtn) {
            startBtn.style.display = 'inline-block';
            startBtn.replaceChildren();
            var icon = document.createElement('i');
            icon.className = 'fas fa-redo';
            startBtn.appendChild(icon);
            startBtn.appendChild(document.createTextNode(' Play Again'));
          }
          grid.replaceChildren();
        } else {
          instruction.replaceChildren();
          var span = document.createElement('span');
          span.style.color = 'var(--green)';
          span.textContent = '🎉 Yay! Correct! Great job!';
          instruction.appendChild(span);
          speakText("Yay! Correct! Great job!");

          setTimeout(function() {
            generateQuizQuestion();
          }, 2200);
        }
      } else {
        this.style.animation = 'wiggle 0.5s ease';
        var cardEl = this;
        setTimeout(function() { cardEl.style.animation = ''; }, 500);

        playSynthChime(180, 'sawtooth');
        speakText("No, that is the " + item.spoken + ". Can you find the " + quizCorrectItem.spoken + "?");
      }
    });

    grid.appendChild(card);
  });
}

var quizStartBtn = document.getElementById('quizStartBtn');
if (quizStartBtn) {
  quizStartBtn.addEventListener('click', function() {
    quizActive = true;
    quizScore = 0;
    document.getElementById('quizScoreValue').textContent = "0 / 5";
    this.style.display = 'none';
    generateQuizQuestion();
  });
}

