// Scrollspy Active Navigation Highlight
// --------------------------------------------------
var scrollSections = document.querySelectorAll('#secHero, #secCategories, #secVideos, #secABC, #secCounting, #secHindi, #secAnimals, #secColors, #secQuiz');
var navLinks = document.querySelectorAll('.header-nav a, .mobile-nav a, .bottom-nav-item');

function updateScrollspy() {
  var scrollPos = window.scrollY || document.documentElement.scrollTop;
  var activeSectionId = '';

  scrollSections.forEach(function(section) {
    var top = section.offsetTop - 120;
    var height = section.offsetHeight;
    if (scrollPos >= top && scrollPos < top + height) {
      activeSectionId = '#' + section.getAttribute('id');
    }
  });

  if (activeSectionId) {
    navLinks.forEach(function(link) {
      link.classList.remove('active');
      var href = link.getAttribute('href') || '';
      if (href.indexOf(activeSectionId) !== -1 || (activeSectionId === '#secHero' && (href === '/' || href.indexOf('#') === -1))) {
        link.classList.add('active');
      }
    });
  }
}

window.addEventListener('scroll', updateScrollspy, { passive: true });
