// --------------------------------------------------
// Gamification DB & State Manager
// --------------------------------------------------
var GamificationDB = {
  data: {
    stars: 0,
    streak: 0,
    level: 1,
    xp: 0,
    lastActiveDate: '',
    completedQuizzes: 0,
    cardsMatched: 0,
    lettersTraced: 0,
    activityLog: [],
    badges: [],
    dailyChallenge: {
      date: '',
      starsEarnedToday: 0,
      tracedToday: 0,
      memoryMatchedToday: 0,
      claimed: [false, false, false]
    }
  },

  load: function() {
    var stored = localStorage.getItem('pogotunes_gamification');
    if (stored) {
      try {
        this.data = JSON.parse(stored);
        if (!this.data.badges) this.data.badges = [];
        if (!this.data.dailyChallenge) {
          this.data.dailyChallenge = {
            date: '',
            starsEarnedToday: 0,
            tracedToday: 0,
            memoryMatchedToday: 0,
            claimed: [false, false, false]
          };
        }
        this.verifyStreak();
      } catch (e) {}
    } else {
      this.data.lastActiveDate = new Date().toDateString();
      this.data.streak = 1;
      this.data.badges = [];
      this.data.dailyChallenge = {
        date: new Date().toDateString(),
        starsEarnedToday: 0,
        tracedToday: 0,
        memoryMatchedToday: 0,
        claimed: [false, false, false]
      };
      this.save();
    }
    this.initDailyChallenge();
    this.updateHUD();
    this.updateAchievementsUI();
  },

  save: function() {
    localStorage.setItem('pogotunes_gamification', JSON.stringify(this.data));
    this.updateHUD();
    this.updateDailyChallengeUI();
  },

  verifyStreak: function() {
    var today = new Date().toDateString();
    if (this.data.lastActiveDate !== today) {
      var yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      if (this.data.lastActiveDate === yesterday.toDateString()) {
        this.data.streak++;
      } else {
        this.data.streak = 1;
      }
      this.data.lastActiveDate = today;
      this.save();
    }
  },

  addStars: function(amount, reason) {
    this.data.stars += amount;
    this.data.xp += amount * 10;

    // Increment daily challenge stars metric
    this.incrementDailyMetric('starsEarnedToday', amount);

    // Check level up (every 100 XP is a level)
    var newLevel = Math.floor(this.data.xp / 100) + 1;
    if (newLevel > this.data.level) {
      this.data.level = newLevel;
      setTimeout(function() {
        speakText("Congratulations! You leveled up to Level " + newLevel + "!");
        triggerConfetti(window.innerWidth / 2, window.innerHeight / 2, '#FFD93D');
        playLevelUpFanfare();
      }, 500);
    }

    this.logActivity(reason + " (+" + amount + " stars)");
    this.checkAchievements();
    this.save();
    this.checkUnlocks();
  },

  logActivity: function(logText) {
    var todayStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    this.data.activityLog.unshift(todayStr + " - " + logText);
    if (this.data.activityLog.length > 30) this.data.activityLog.pop();
  },

  updateHUD: function() {
    var streakEl = document.getElementById('headerStreakVal');
    var starsEl = document.getElementById('headerStarsVal');
    if (streakEl) streakEl.textContent = this.data.streak;
    if (starsEl) starsEl.textContent = this.data.stars;
  },

  initDailyChallenge: function() {
    var today = new Date().toDateString();
    if (!this.data.dailyChallenge) {
      this.data.dailyChallenge = {
        date: today,
        starsEarnedToday: 0,
        tracedToday: 0,
        memoryMatchedToday: 0,
        claimed: [false, false, false]
      };
    }
    if (this.data.dailyChallenge.date !== today) {
      this.data.dailyChallenge.date = today;
      this.data.dailyChallenge.starsEarnedToday = 0;
      this.data.dailyChallenge.tracedToday = 0;
      this.data.dailyChallenge.memoryMatchedToday = 0;
      this.data.dailyChallenge.claimed = [false, false, false];
    }
    this.updateDailyChallengeUI();
  },

  incrementDailyMetric: function(metric, amount) {
    this.initDailyChallenge();
    this.data.dailyChallenge[metric] += amount;
    this.checkDailyGoals();
    this.save();
  },

  checkDailyGoals: function() {
    var dc = this.data.dailyChallenge;
    var self = this;

    // Goal 1: Earn 15 stars today
    if (dc.starsEarnedToday >= 15 && !dc.claimed[0]) {
      dc.claimed[0] = true;
      self.awardDailyBonus(0, "Earned 15 stars today!");
    }
    // Goal 2: Trace 2 letters/numbers
    if (dc.tracedToday >= 2 && !dc.claimed[1]) {
      dc.claimed[1] = true;
      self.awardDailyBonus(1, "Traced 2 letters today!");
    }
    // Goal 3: Complete 1 memory match
    if (dc.memoryMatchedToday >= 1 && !dc.claimed[2]) {
      dc.claimed[2] = true;
      self.awardDailyBonus(2, "Completed a memory match today!");
    }
  },

  awardDailyBonus: function(index, title) {
    var self = this;
    setTimeout(function() {
      speakText("Awesome! You completed a daily challenge: " + title);
      triggerConfetti(window.innerWidth / 2, window.innerHeight / 2, '#6EE7B7');
      playLevelUpFanfare();

      self.data.stars += 10;
      self.data.xp += 100;
      self.logActivity("Daily Challenge Completed (+10 stars)");

      var newLevel = Math.floor(self.data.xp / 100) + 1;
      if (newLevel > self.data.level) {
        self.data.level = newLevel;
        setTimeout(function() {
          speakText("Congratulations! You leveled up to Level " + newLevel + "!");
          triggerConfetti(window.innerWidth / 2, window.innerHeight / 2, '#FFD93D');
          playLevelUpFanfare();
        }, 500);
      }

      self.checkAchievements();
      self.save();
      self.checkUnlocks();
    }, 800);
  },

  updateDailyChallengeUI: function() {
    var dc = this.data.dailyChallenge;
    if (!dc) return;

    var elStars = document.getElementById('challenge-stars-prog');
    var elTrace = document.getElementById('challenge-trace-prog');
    var elMemory = document.getElementById('challenge-memory-prog');

    if (elStars) {
      elStars.textContent = Math.min(dc.starsEarnedToday, 15) + "/15";
      var parent = elStars.closest('.challenge-item');
      if (dc.claimed[0] && parent) parent.classList.add('completed');
      else if (parent) parent.classList.remove('completed');
    }
    if (elTrace) {
      elTrace.textContent = Math.min(dc.tracedToday, 2) + "/2";
      var parent = elTrace.closest('.challenge-item');
      if (dc.claimed[1] && parent) parent.classList.add('completed');
      else if (parent) parent.classList.remove('completed');
    }
    if (elMemory) {
      elMemory.textContent = Math.min(dc.memoryMatchedToday, 1) + "/1";
      var parent = elMemory.closest('.challenge-item');
      if (dc.claimed[2] && parent) parent.classList.add('completed');
      else if (parent) parent.classList.remove('completed');
    }
  },

  checkAchievements: function() {
    if (!this.data.badges) this.data.badges = [];
    var earnedNew = false;
    var self = this;

    // 1. star_collector: 50 stars
    if (self.data.stars >= 50 && self.data.badges.indexOf('star_collector') === -1) {
      self.data.badges.push('star_collector');
      self.announceBadge("Star Collector", "🌟");
      earnedNew = true;
    }
    // 2. streak_champ: streak >= 3
    if (self.data.streak >= 3 && self.data.badges.indexOf('streak_champ') === -1) {
      self.data.badges.push('streak_champ');
      self.announceBadge("Streak Champ", "🔥");
      earnedNew = true;
    }
    // 3. magic_writer: 5 letters traced
    if (self.data.lettersTraced >= 5 && self.data.badges.indexOf('magic_writer') === -1) {
      self.data.badges.push('magic_writer');
      self.announceBadge("Magic Writer", "✏️");
      earnedNew = true;
    }
    // 4. brainy_kid: 3 quizzes completed
    if (self.data.completedQuizzes >= 3 && self.data.badges.indexOf('brainy_kid') === -1) {
      self.data.badges.push('brainy_kid');
      self.announceBadge("Brainy Kid", "🧠");
      earnedNew = true;
    }
    // 5. memory_master: 32 memory cards matched (2 full matches)
    if (self.data.cardsMatched >= 32 && self.data.badges.indexOf('memory_master') === -1) {
      self.data.badges.push('memory_master');
      self.announceBadge("Memory Master", "🧩");
      earnedNew = true;
    }

    if (earnedNew) {
      self.save();
      self.updateAchievementsUI();
    }
  },

  announceBadge: function(name, emoji) {
    var self = this;
    setTimeout(function() {
      speakText("Hurray! You earned the " + name + " badge!");
      var bubble = document.getElementById('mascotSpeechVal');
      if (bubble) {
        bubble.replaceChildren();
        bubble.appendChild(document.createTextNode('🎉 Wow! You earned the '));
        var strong = document.createElement('strong');
        strong.textContent = emoji + ' ' + name;
        bubble.appendChild(strong);
        bubble.appendChild(document.createTextNode(' badge! Keep it up!'));
      }
      triggerConfetti(window.innerWidth / 2, window.innerHeight / 2, '#B28DFF');
      playLevelUpFanfare();
      self.data.stars += 20;
      self.logActivity("Earned Badge: " + name + " (+20 stars)");
      self.save();
    }, 1200);
  },

  updateAchievementsUI: function() {
    var badges = this.data.badges || [];
    var badgeIds = ['star_collector', 'streak_champ', 'magic_writer', 'brainy_kid', 'memory_master'];
    badgeIds.forEach(function(id) {
      var el = document.getElementById('badge_' + id);
      if (el) {
        if (badges.indexOf(id) !== -1) {
          el.classList.remove('locked');
        } else {
          el.classList.add('locked');
        }
      }
    });
  },

  checkUnlocks: function() {
    var stars = this.data.stars;
    var cards = document.querySelectorAll('.category-card');

    // Unlock thresholds
    var locks = {
      'abcs': 0,
      '123s': 20,
      'colors': 40,
      'animals': 60,
      'hindi': 80,
      'songs': 100
    };

    cards.forEach(function(card) {
      var name = card.querySelector('.cat-name');
      if (name) {
        var key = name.textContent.toLowerCase();
        var limit = locks[key] || 0;
        if (stars < limit) {
          card.classList.add('locked');
          card.setAttribute('title', 'Unlock at ' + limit + ' Stars!');
        } else {
          card.classList.remove('locked');
          card.removeAttribute('title');
        }
      }
    });
  },

  reset: function() {
    this.data = {
      stars: 0,
      streak: 1,
      level: 1,
      xp: 0,
      lastActiveDate: new Date().toDateString(),
      completedQuizzes: 0,
      cardsMatched: 0,
      lettersTraced: 0,
      activityLog: ["Progress reset by parent."],
      badges: [],
      dailyChallenge: {
        date: new Date().toDateString(),
        starsEarnedToday: 0,
        tracedToday: 0,
        memoryMatchedToday: 0,
        claimed: [false, false, false]
      }
    };
    this.save();
    this.checkUnlocks();
    this.updateAchievementsUI();
    this.initDailyChallenge();
  }
};

function playLevelUpFanfare() {
  if (soundMuted) return;
  var notes = [261.63, 329.63, 392.00, 523.25, 659.25, 783.99, 1046.50];
  notes.forEach(function(freq, index) {
    setTimeout(function() {
      playSynthChime(freq, 'sine');
    }, index * 80);
  });
}

// --------------------------------------------------
// Tab Switching Game Center
// --------------------------------------------------
var tabButtons = document.querySelectorAll('.game-tab-btn');
var gamePanels = document.querySelectorAll('.game-panel');
var mascotSpeech = document.getElementById('mascotSpeechVal');

tabButtons.forEach(function(btn) {
  btn.addEventListener('click', function() {
    tabButtons.forEach(function(b) { b.classList.remove('active'); });
    gamePanels.forEach(function(p) { p.classList.remove('active'); });

    this.classList.add('active');
    var target = this.getAttribute('data-target');
    var panel = document.getElementById(target);
    if (panel) panel.classList.add('active');

    playSynthChime(440, 'sine');

    if (target === 'panelQuiz') {
      mascotSpeech.textContent = "Welcome to the quiz! Let's test your brain!";
      speakText(mascotSpeech.textContent);
    } else if (target === 'panelDragDrop') {
      mascotSpeech.textContent = "Can you drag animal cards to matching baskets?";
      speakText(mascotSpeech.textContent);
      initDragDropGame();
    } else if (target === 'panelMemory') {
      mascotSpeech.textContent = "Flip the cards to match pairs of cute animals!";
      speakText(mascotSpeech.textContent);
      initMemoryGame();
    } else if (target === 'panelTracing') {
      mascotSpeech.textContent = "Let's learn writing! Draw on the dotted line!";
      speakText(mascotSpeech.textContent);
      initTracingGame();
    }
  });
});

// Hook Category Card Lock Checks
document.querySelectorAll('.category-card').forEach(function(card) {
  card.addEventListener('click', function(e) {
    if (this.classList.contains('locked')) {
      e.preventDefault();
      e.stopPropagation();
      var starsRequired = this.getAttribute('title');
      speakText("This category is locked. Play games to earn stars and unlock it!");
      this.style.animation = 'wiggle 0.5s ease';
      var that = this;
      setTimeout(function() { that.style.animation = ''; }, 500);
      playSynthChime(150, 'triangle');
      return;
    }
  });
});

// --------------------------------------------------
// Memory Matching Game Logic
// --------------------------------------------------
var memoryItems = ['🐶', '🐱', '🐘', '🦁', '🐒', '🐦', '🐟', '🐄'];
var firstCard = null;
var secondCard = null;
var isBoardLocked = false;
var pairsMatched = 0;

function initMemoryGame() {
  var grid = document.getElementById('memoryGrid');
  if (!grid) return;
  grid.replaceChildren();
  firstCard = null;
  secondCard = null;
  isBoardLocked = false;
  pairsMatched = 0;
  var pairsVal = document.getElementById('memoryPairsVal');
  if (pairsVal) pairsVal.textContent = 0;

  var cardItems = memoryItems.concat(memoryItems);
  cardItems.sort(function() { return 0.5 - Math.random(); });

  cardItems.forEach(function(emoji) {
    var card = document.createElement('div');
    card.className = 'memory-card';
    card.replaceChildren();
    var s1 = document.createElement('span');
    s1.className = 'card-back';
    s1.textContent = '❓';
    var s2 = document.createElement('span');
    s2.className = 'card-front';
    s2.textContent = emoji;
    card.appendChild(s1);
    card.appendChild(s2);

    card.addEventListener('click', function() {
      if (isBoardLocked) return;
      if (this === firstCard) return;
      if (this.classList.contains('matched') || this.classList.contains('flipped')) return;

      playSynthChime(330, 'sine');
      this.classList.add('flipped');

      if (!firstCard) {
        firstCard = this;
      } else {
        secondCard = this;
        checkMemoryMatch();
      }
    });

    grid.appendChild(card);
  });
}

function checkMemoryMatch() {
  isBoardLocked = true;
  var emoji1 = firstCard.querySelector('.card-front').textContent;
  var emoji2 = secondCard.querySelector('.card-front').textContent;

  if (emoji1 === emoji2) {
    firstCard.classList.add('matched');
    secondCard.classList.add('matched');
    pairsMatched++;
    var pairsVal = document.getElementById('memoryPairsVal');
    if (pairsVal) pairsVal.textContent = pairsMatched;

    playSynthChime(523.25, 'sine');
    setTimeout(function() { playSynthChime(659.25, 'sine'); }, 80);

    var rect1 = firstCard.getBoundingClientRect();
    triggerConfetti(rect1.left + rect1.width/2, rect1.top + rect1.height/2, '#6EE7B7');

    firstCard = null;
    secondCard = null;
    isBoardLocked = false;

    if (pairsMatched === memoryItems.length) {
      setTimeout(function() {
        speakText("Fantastic! You matched all animal friends!");
        triggerConfetti(window.innerWidth / 2, window.innerHeight / 2, '#FFD93D');
        playLevelUpFanfare();
        GamificationDB.data.cardsMatched += 16;
        GamificationDB.incrementDailyMetric('memoryMatchedToday', 1);
        GamificationDB.addStars(10, "Completed Animal Memory Match!");
      }, 500);
    }
  } else {
    setTimeout(function() {
      if (firstCard) firstCard.classList.remove('flipped');
      if (secondCard) secondCard.classList.remove('flipped');
      firstCard = null;
      secondCard = null;
      isBoardLocked = false;
    }, 1000);
  }
}

var memoryStartBtn = document.getElementById('memoryStartBtn');
if (memoryStartBtn) {
  memoryStartBtn.addEventListener('click', initMemoryGame);
}

// --------------------------------------------------
// Drag & Drop / Tap Matching Logic
// --------------------------------------------------
var dragItems = [
  { emoji: '🐶', name: 'Dog' },
  { emoji: '🐱', name: 'Cat' },
  { emoji: '🐘', name: 'Elephant' },
  { emoji: '🦁', name: 'Lion' },
  { emoji: '🐒', name: 'Monkey' },
  { emoji: '🐄', name: 'Cow' }
];

var activeDragItemData = null;
var activeSelectedCard = null;
var dragMatchedCount = 0;

function initDragDropGame() {
  var srcRow = document.getElementById('dragSourceRow');
  var destRow = document.getElementById('dragTargetRow');
  if (!srcRow || !destRow) return;

  srcRow.replaceChildren();
  destRow.replaceChildren();
  activeDragItemData = null;
  activeSelectedCard = null;
  dragMatchedCount = 0;
  document.getElementById('dragScoreVal').textContent = 0;
  document.getElementById('dragInstructionText').textContent = "Tap a card, then tap its matching basket!";

  var itemsCopy = dragItems.slice();
  var selected = [];
  while (selected.length < 3 && itemsCopy.length > 0) {
    var randIndex = Math.floor(Math.random() * itemsCopy.length);
    selected.push(itemsCopy.splice(randIndex, 1)[0]);
  }

  var draggables = selected.slice().sort(function() { return 0.5 - Math.random(); });
  var targets = selected.slice().sort(function() { return 0.5 - Math.random(); });

  draggables.forEach(function(item) {
    var card = document.createElement('div');
    card.className = 'drag-card';
    card.setAttribute('draggable', 'true');
    card.textContent = item.emoji;

    card.addEventListener('dragstart', function(e) {
      activeDragItemData = item;
      activeSelectedCard = this;
      e.dataTransfer.setData('text/plain', item.name);
      this.style.opacity = '0.5';
    });

    card.addEventListener('dragend', function() {
      this.style.opacity = '1';
    });

    card.addEventListener('click', function(e) {
      playSynthChime(280, 'sine');
      document.querySelectorAll('.drag-card').forEach(function(c) { c.style.borderColor = 'var(--blue)'; });
      this.style.borderColor = 'var(--purple)';
      activeDragItemData = item;
      activeSelectedCard = this;
      document.getElementById('dragInstructionText').textContent = "Now tap the matching named basket!";
    });

    srcRow.appendChild(card);
  });

  targets.forEach(function(item) {
    var zone = document.createElement('div');
    zone.className = 'drag-zone';
    zone.textContent = '🧺 ' + item.name;

    zone.addEventListener('dragover', function(e) {
      e.preventDefault();
      this.classList.add('drag-hover');
    });

    zone.addEventListener('dragleave', function() {
      this.classList.remove('drag-hover');
    });

    zone.addEventListener('drop', function(e) {
      e.preventDefault();
      this.classList.remove('drag-hover');
      var name = e.dataTransfer.getData('text/plain');
      if (name === item.name && activeSelectedCard) {
        handleMatchedDrag(activeSelectedCard, this, item);
      } else {
        playSynthChime(150, 'sawtooth');
      }
    });

    zone.addEventListener('click', function() {
      if (activeDragItemData && activeSelectedCard) {
        if (activeDragItemData.name === item.name) {
          handleMatchedDrag(activeSelectedCard, this, item);
        } else {
          this.style.animation = 'wiggle 0.5s ease';
          var zoneEl = this;
          setTimeout(function() { zoneEl.style.animation = ''; }, 500);
          playSynthChime(150, 'sawtooth');
          speakText("No, that is not the basket for " + activeDragItemData.name);
        }
      }
    });

    destRow.appendChild(zone);
  });
}

function handleMatchedDrag(card, zone, item) {
  card.style.visibility = 'hidden';
  zone.classList.add('matched');
  zone.textContent = '✨ ' + item.emoji + ' ' + item.name;

  playSynthChime(440, 'sine');
  setTimeout(function() { playSynthChime(554.37, 'sine'); }, 80);

  var rect = zone.getBoundingClientRect();
  triggerConfetti(rect.left + rect.width / 2, rect.top + rect.height / 2, '#6BCBFF');

  dragMatchedCount++;
  document.getElementById('dragScoreVal').textContent = dragMatchedCount;
  activeDragItemData = null;
  activeSelectedCard = null;

  if (dragMatchedCount === 3) {
    setTimeout(function() {
      speakText("Wonderful! You sorted all the baskets!");
      triggerConfetti(window.innerWidth / 2, window.innerHeight / 2, '#FFD93D');
      playLevelUpFanfare();
      GamificationDB.addStars(10, "Completed Drag & Drop Animal Sorting!");
    }, 500);
  }
}

var dragStartBtn = document.getElementById('dragStartBtn');
if (dragStartBtn) {
  dragStartBtn.addEventListener('click', initDragDropGame);
}

// --------------------------------------------------
// Canvas Letter Tracing Logic
// --------------------------------------------------
var tracingLetters = ['A', 'B', 'C', 'D', 'E', '1', '2', '3', '4', '5'];
var currentTracingIndex = 0;
var tracingCanvas = document.getElementById('tracingCanvas');
var tracingCtx = null;
var isDrawing = false;
var hasDrawn = false;

function initTracingGame() {
  if (!tracingCanvas) return;
  tracingCtx = tracingCanvas.getContext('2d');

  tracingCanvas.width = 320;
  tracingCanvas.height = 320;

  clearTracingCanvas();
  loadTracingLetter();

  tracingCanvas.addEventListener('mousedown', startTracing);
  tracingCanvas.addEventListener('mousemove', traceMove);
  tracingCanvas.addEventListener('mouseup', stopTracing);
  tracingCanvas.addEventListener('mouseleave', stopTracing);

  tracingCanvas.addEventListener('touchstart', function(e) {
    e.preventDefault();
    var touch = e.touches[0];
    var rect = tracingCanvas.getBoundingClientRect();
    startTracing({ clientX: touch.clientX, clientY: touch.clientY });
  });

  tracingCanvas.addEventListener('touchmove', function(e) {
    e.preventDefault();
    var touch = e.touches[0];
    traceMove({ clientX: touch.clientX, clientY: touch.clientY });
  });

  tracingCanvas.addEventListener('touchend', stopTracing);
}

function clearTracingCanvas() {
  if (!tracingCtx) return;
  tracingCtx.clearRect(0, 0, tracingCanvas.width, tracingCanvas.height);
  hasDrawn = false;
}

function loadTracingLetter() {
  var letter = tracingLetters[currentTracingIndex];
  document.getElementById('tracingGuideLetter').textContent = letter;
  document.getElementById('tracingInstructionText').textContent = "Trace the letter " + letter + "!";
  speakText("Trace the letter " + letter);
}

function getCanvasCoords(e) {
  var rect = tracingCanvas.getBoundingClientRect();
  var x = ((e.clientX - rect.left) / rect.width) * tracingCanvas.width;
  var y = ((e.clientY - rect.top) / rect.height) * tracingCanvas.height;
  return { x: x, y: y };
}

function startTracing(e) {
  isDrawing = true;
  var coords = getCanvasCoords(e);
  tracingCtx.beginPath();
  tracingCtx.moveTo(coords.x, coords.y);
  tracingCtx.lineWidth = 14;
  tracingCtx.lineCap = 'round';
  tracingCtx.lineJoin = 'round';
  tracingCtx.strokeStyle = 'var(--coral)';
}

function traceMove(e) {
  if (!isDrawing) return;
  var coords = getCanvasCoords(e);
  tracingCtx.lineTo(coords.x, coords.y);
  tracingCtx.stroke();
  hasDrawn = true;

  if (Math.random() < 0.15) {
    playSynthChime(440 + Math.random() * 200, 'sine');
  }
}

function stopTracing() {
  if (isDrawing) {
    tracingCtx.closePath();
    isDrawing = false;
  }
}

var tracingClearBtn = document.getElementById('tracingClearBtn');
if (tracingClearBtn) {
  tracingClearBtn.addEventListener('click', clearTracingCanvas);
}

var tracingNextBtn = document.getElementById('tracingNextBtn');
if (tracingNextBtn) {
  tracingNextBtn.addEventListener('click', function() {
    if (!hasDrawn) {
      speakText("Draw first to trace the letter!");
      return;
    }

    triggerConfetti(window.innerWidth / 2, window.innerHeight / 2, '#FF6B6B');
    playSynthChime(523.25, 'sine');
    setTimeout(function() { playSynthChime(659.25, 'sine'); }, 100);

    GamificationDB.data.lettersTraced++;
    GamificationDB.incrementDailyMetric('tracedToday', 1);
    GamificationDB.addStars(5, "Traced letter " + tracingLetters[currentTracingIndex]);

    var xpEarnedEl = document.getElementById('tracingXPVal');
    if (xpEarnedEl) xpEarnedEl.textContent = GamificationDB.data.lettersTraced * 5;

    currentTracingIndex = (currentTracingIndex + 1) % tracingLetters.length;
    clearTracingCanvas();
    loadTracingLetter();
  });
}

// --------------------------------------------------
// Parent Portal Logic
// --------------------------------------------------
var parentAnswer = 0;
var deferredInstallPrompt = null;

window.addEventListener('beforeinstallprompt', function(e) {
  e.preventDefault();
  deferredInstallPrompt = e;
  var container = document.getElementById('pwaInstallContainer');
  if (container) container.style.display = 'block';
});

var openParentBtn = document.getElementById('openParentPortalBtn');
var parentGateModal = document.getElementById('parentGateModal');
var parentDashboardModal = document.getElementById('parentDashboardModal');
var closeGateBtn = document.getElementById('closeParentGateBtn');
var closeDashboardBtn = document.getElementById('closeParentDashboardBtn');
var closeDashboardBtn2 = document.getElementById('closeParentPortalBtn2');

if (openParentBtn && parentGateModal) {
  openParentBtn.addEventListener('click', function(e) {
    e.preventDefault();
    closeMenu();

    var num1 = Math.floor(Math.random() * 15) + 5;
    var num2 = Math.floor(Math.random() * 10) + 2;
    parentAnswer = num1 + num2;
    document.getElementById('parentMathQuestion').textContent = num1 + " + " + num2 + " = ?";
    document.getElementById('parentGateAnswer').value = '';
    document.getElementById('parentGateFeedback').textContent = '';

    parentGateModal.style.display = 'flex';
  });
}

if (closeGateBtn) {
  closeGateBtn.addEventListener('click', function() {
    parentGateModal.style.display = 'none';
  });
}

if (closeDashboardBtn) {
  closeDashboardBtn.addEventListener('click', function() {
    parentDashboardModal.style.display = 'none';
  });
}
if (closeDashboardBtn2) {
  closeDashboardBtn2.addEventListener('click', function() {
    parentDashboardModal.style.display = 'none';
  });
}

var parentGateForm = document.getElementById('parentGateForm');
if (parentGateForm) {
  parentGateForm.addEventListener('submit', function() {
    var ans = parseInt(document.getElementById('parentGateAnswer').value);
    if (ans === parentAnswer) {
      parentGateModal.style.display = 'none';
      openParentDashboard();
    } else {
      document.getElementById('parentGateFeedback').textContent = "Incorrect answer! Try again.";
      playSynthChime(150, 'sawtooth');
    }
  });
}

function openParentDashboard() {
  if (!parentDashboardModal) return;

  document.getElementById('parentStatLevel').textContent = "Level " + GamificationDB.data.level;
  document.getElementById('parentStatStreak').textContent = GamificationDB.data.streak + " Days";
  document.getElementById('parentStatStars').textContent = GamificationDB.data.stars + " ⭐";
  document.getElementById('parentStatGames').textContent = GamificationDB.data.completedQuizzes + Math.floor(GamificationDB.data.cardsMatched / 16) + GamificationDB.data.lettersTraced;

  var badgeContainer = document.getElementById('parentBadgesContainer');
  if (badgeContainer) {
    badgeContainer.replaceChildren();
    var badges = GamificationDB.data.badges || [];
    if (badges.length === 0) {
      badgeContainer.replaceChildren();
      var span = document.createElement('span');
      span.style.fontSize = '0.9rem';
      span.style.color = 'var(--gray)';
      span.textContent = 'No badges earned yet. Keep learning!';
      badgeContainer.appendChild(span);
    } else {
      var badgeMap = {
        'star_collector': { emoji: '🌟', title: 'Star Collector' },
        'streak_champ': { emoji: '🔥', title: 'Streak Champ' },
        'magic_writer': { emoji: '✏️', title: 'Magic Writer' },
        'brainy_kid': { emoji: '🧠', title: 'Brainy Kid' },
        'memory_master': { emoji: '🧩', title: 'Memory Master' }
      };
      badges.forEach(function(badgeKey) {
        var info = badgeMap[badgeKey];
        if (info) {
          var span = document.createElement('span');
          span.textContent = info.emoji;
          span.setAttribute('title', info.title);
          span.style.cursor = 'help';
          span.style.marginRight = '8px';
          badgeContainer.appendChild(span);
        }
      });
    }
  }

  var logsList = document.getElementById('parentActivityLog');
  if (logsList) {
    logsList.replaceChildren();
    if (GamificationDB.data.activityLog.length === 0) {
      logsList.replaceChildren();
      var li = document.createElement('li');
      li.textContent = 'No activity logged yet!';
      logsList.appendChild(li);
    } else {
      GamificationDB.data.activityLog.forEach(function(log) {
        var li = document.createElement('li');
        li.textContent = log;
        logsList.appendChild(li);
      });
    }
  }

  parentDashboardModal.style.display = 'flex';
}

var installBtn = document.getElementById('pwaInstallBtn');
if (installBtn) {
  installBtn.addEventListener('click', function() {
    if (deferredInstallPrompt) {
      deferredInstallPrompt.prompt();
      deferredInstallPrompt.userChoice.then(function(choiceResult) {
        deferredInstallPrompt = null;
        var container = document.getElementById('pwaInstallContainer');
        if (container) container.style.display = 'none';
      });
    }
  });
}

var resetBtn = document.getElementById('resetProgressBtn');
if (resetBtn) {
  resetBtn.addEventListener('click', function() {
    if (confirm("Are you sure you want to reset all learning progress? This cannot be undone!")) {
      GamificationDB.reset();
      parentDashboardModal.style.display = 'none';
      speakText("Learning progress reset.");
    }
  });
}

