body.script:
//
document.addEventListener('DOMContentLoaded', function() {
  const dynamicWidgets = document.querySelectorAll('.cms-dynamic-widget');
  dynamicWidgets.forEach(widget => {
    const label = widget.getAttribute('data-label');
    const max = widget.getAttribute('data-max') || 4;

    if(!label) return;

    fetch('/feeds/posts/summary/-/' + encodeURIComponent(label) + '?alt=json&max-results=' + max)
      .then(res => res.json())
      .then(data => {
        let html = '';
        if (data.feed.entry && data.feed.entry.length > 0) {
          html += '<div class=\"blog-posts-grid\">';
          data.feed.entry.forEach(entry => {
            const title = entry.title.$t;
            const url = entry.link.find(l => l.rel === 'alternate').href;
            const imgRaw = entry.media$thumbnail ? entry.media$thumbnail.url : '';
            const img = imgRaw ? imgRaw.replace('/s72-c', '/s400') : '';
            const snippet = entry.summary ? entry.summary.$t.substring(0, 100) + '...' : '';

            html += '<div class=\"blog-post-card fade-in\">';
            if (img) {
              html += '<img class=\"post-featured-img\" src=\"' + img + '\" alt=\"' + title + '\"/>';
            } else {
              html += '<div class=\"post-gradient-placeholder\" style=\"background:linear-gradient(135deg,#ffb6b9,#d5a6bd,#a1e3d8)\">&#127925;</div>';
            }
            html += '<div class=\"post-content\">';
            html += '<h2><a href=\"' + url + '\">' + title + '</a></h2>';
            html += '<div class=\"post-snippet\">' + snippet + '</div>';
            html += '<a class=\"read-more-link\" href=\"' + url + '\">Watch/Read <i class=\"fas fa-arrow-right\"></i></a>';
            html += '</div></div>';
          });
          html += '</div>';
        } else {
          html += '<p style=\"text-align:center;color:var(--gray)\">No posts found in ' + label + '</p>';
        }
        widget.innerHTML = html;
      })
      .catch(err => {
        console.error('Feed error:', err);
      });
  });
});
